class _ProjectLoadWorker(QtCore.QObject):
    """One-shot project loader; no SQLite object crosses thread boundaries."""

    loaded = QtCore.Signal(str, object, object)
    failed = QtCore.Signal(str, str, str, bool)
    finished = QtCore.Signal()

    def __init__(self, project_path: str) -> None:
        super().__init__()
        self._project_path = str(project_path)

    @QtCore.Slot()
    def run(self) -> None:
        try:
            from app.io.project import load_project_for_editing
            from app.project_edits.ledger import ProjectEditLedger
            from app.ui.shell.project_projection import project_ui_projection

            project = load_project_for_editing(self._project_path)
            ledger = ProjectEditLedger.from_dict(project["edit_ledger"])
            projection = project_ui_projection(
                project,
                ledger,
                project_path=self._project_path,
            )
            self.loaded.emit(self._project_path, project, projection)
        except Exception as exc:  # typed UI boundary; never parse this text.
            self.failed.emit(
                self._project_path,
                "project_load_failed",
                f"{type(exc).__name__}: {exc}",
                True,
            )
        finally:
            self.finished.emit()


def _windows_resize_hit_test(
    global_x: int,
    global_y: int,
    window_rect: tuple[int, int, int, int],
    border: int,
) -> int:
    """Return a Windows resize hit code using physical screen coordinates."""

    frame_left, frame_top, frame_right, frame_bottom = window_rect
    left = global_x < frame_left + border
    right = global_x >= frame_right - border
    top = global_y < frame_top + border
    bottom = global_y >= frame_bottom - border
    if top and left:
        return 13  # HTTOPLEFT
    if top and right:
        return 14  # HTTOPRIGHT
    if bottom and left:
        return 16  # HTBOTTOMLEFT
    if bottom and right:
        return 17  # HTBOTTOMRIGHT
    if left:
        return 10  # HTLEFT
    if right:
        return 11  # HTRIGHT
    if top:
        return 12  # HTTOP
    if bottom:
        return 15  # HTBOTTOM
    return 0


