    @staticmethod
    def _configuration_root() -> Path:
        local_app_data = os.environ.get("LOCALAPPDATA")
        if local_app_data:
            return Path(local_app_data) / "YomiFrame" / "config"
        fallback = QtCore.QStandardPaths.writableLocation(
            QtCore.QStandardPaths.StandardLocation.AppConfigLocation
        )
        return Path(fallback or os.getcwd()) / "YomiFrame"

    def _wire_one_shot_thread(
        self,
        *,
        thread: QtCore.QThread,
        worker: QtCore.QObject,
        thread_attribute: str,
        worker_attribute: str,
        on_settled: Callable[[], None],
    ) -> None:
        """Retain and settle one-shot worker ownership on the GUI thread."""

        if getattr(self, thread_attribute) is not None:
            raise RuntimeError(f"{thread_attribute} already owns a running thread")
        if getattr(self, worker_attribute) is not None:
            raise RuntimeError(f"{worker_attribute} already owns a running worker")
        settlement_key = id(thread)
        if settlement_key in self._one_shot_thread_settlements:
            raise RuntimeError("one-shot thread is already wired")

        setattr(self, thread_attribute, thread)
        setattr(self, worker_attribute, worker)
        self._one_shot_thread_settlements[settlement_key] = (
            thread,
            worker,
            thread_attribute,
            worker_attribute,
            on_settled,
        )
        worker.finished.connect(
            thread.quit,
            QtCore.Qt.ConnectionType.DirectConnection,
        )
        worker.finished.connect(worker.deleteLater)
        thread.finished.connect(
            lambda key=settlement_key: (
                self._one_shot_thread_settlement_requested.emit(key)
            ),
            QtCore.Qt.ConnectionType.DirectConnection,
        )

    @QtCore.Slot(object)
    def _settle_one_shot_thread(self, settlement_key: object) -> None:
        if not isinstance(settlement_key, int):
            self._set_notice(
                "A background action supplied an invalid settlement identity; controls remain locked.",
                warning=True,
            )
            return
        settlement = self._one_shot_thread_settlements.get(settlement_key)
        if settlement is None or id(settlement[0]) != settlement_key:
            self._set_notice(
                "A background action lost its thread identity; controls remain locked.",
                warning=True,
            )
            return
        thread, worker, thread_attribute, worker_attribute, on_settled = settlement
        if (
            getattr(self, thread_attribute) is not thread
            or getattr(self, worker_attribute) is not worker
        ):
            self._set_notice(
                "A background action changed ownership before settlement; controls remain locked.",
                warning=True,
            )
            return
        if settlement_key not in self._one_shot_thread_joined:
            try:
                joined = thread.wait()
            except RuntimeError:
                joined = False
            if not joined:
                self._set_notice(
                    "A background action did not stop cleanly; controls remain locked.",
                    warning=True,
                )
                return
            self._one_shot_thread_joined.add(settlement_key)
            # Terminal worker receipts cross to the GUI thread as queued
            # signals. Give those already-posted receipts one complete event
            # turn before making the thread appear settled; otherwise a fast
            # worker can expose a completed thread while its committed/stale/
            # failed presentation is still the previous draft.
            QtCore.QTimer.singleShot(
                0,
                lambda key=settlement_key: (
                    self._one_shot_thread_settlement_requested.emit(key)
                ),
            )
            return

        setattr(self, worker_attribute, None)
        setattr(self, thread_attribute, None)
        self._one_shot_thread_settlements.pop(settlement_key, None)
        self._one_shot_thread_joined.discard(settlement_key)
        thread.deleteLater()
        on_settled()

    def _load_settings_view_model(self) -> SettingsViewModel:
        try:
            document = self._application_store.load()
        except Exception as exc:
            document = ApplicationSettingsDocument()
            self._startup_notice = (
                "Application settings could not be loaded; defaults are shown "
                f"without overwriting the file ({type(exc).__name__})."
            )
        try:
            profiles = self._provider_store.load()
        except Exception as exc:
            profiles = ()
            suffix = f" Provider profiles are unavailable ({type(exc).__name__})."
            self._startup_notice = (self._startup_notice + suffix).strip()
        self._application_document = document
        self._application_module_configs = document.application_module_configs
        configs = self._merged_module_configs(
            document.application_module_configs,
            (),
        )
        return SettingsViewModel(
            SettingsDraft(
                application=document.application_preferences,
                project=ProjectConfig(),
                module_configs=configs,
                provider_profiles=profiles,
            )
        )

    @staticmethod
    def _merged_module_configs(
        application_configs: Iterable[ModuleConfig],
        project_configs: Iterable[ModuleConfig],
    ) -> tuple[ModuleConfig, ...]:
        application_by_id = {item.module_id: item for item in application_configs}
        project_by_id = {item.module_id: item for item in project_configs}
        result: list[ModuleConfig] = []
        for schema in DEFAULT_MODULE_REGISTRY.modules:
            app = application_by_id.get(schema.module_id)
            project = project_by_id.get(schema.module_id)
            values: dict[str, Any] = {}
            legacy: dict[str, Any] = {}
            for value in (app, project):
                if value is None:
                    continue
                values.update(value.values)
                legacy.update(value.legacy_values)
            result.append(
                ModuleConfig(
                    module_id=schema.module_id,
                    module_schema_version=schema.schema_version,
                    values=values,
                    legacy_values=legacy,
                )
            )
        return tuple(result)

    def _build_shell(self) -> None:
        shell = QtWidgets.QWidget()
        shell.setProperty("role", "shell")
        layout = QtWidgets.QVBoxLayout(shell)
