    def _refresh_header_icons(self, theme: str) -> None:
        self._brand_mark.setPixmap(
            hybrid_icon("brand", theme, active=True).pixmap(QtCore.QSize(18, 18))
        )
        for navigation_id, button in self._navigation_buttons.items():
            button.setIcon(
                hybrid_icon(
                    navigation_id,
                    theme,
                    accent=button.isChecked(),
                )
            )
        self._header_undo.setIcon(hybrid_icon("undo", theme))
        self._header_redo.setIcon(hybrid_icon("redo", theme))
        dark = theme == "dark"
        self._header_theme.setIcon(
            hybrid_icon("theme" if dark else "theme-dark", theme)
        )
        self._header_theme.setAccessibleName(
            "Switch to light theme" if dark else "Switch to dark theme"
        )
        self._window_minimize.setIcon(hybrid_icon("minimize", theme))
        self._window_maximize.setIcon(hybrid_icon("maximize", theme))
        self._window_close.setIcon(hybrid_icon("close", theme))
        if hasattr(self, "hub"):
            self.hub.refresh_icons(theme)
        if hasattr(self, "workspace"):
            self.workspace.refresh_icons(theme)
        if hasattr(self, "editor"):
            self.editor.refresh_icons(theme)
        if hasattr(self, "settings"):
            self.settings.refresh_icons(theme)

    def _toggle_header_theme(self) -> None:
        if self._layout_state.theme == "dark":
            self.settings.light_theme.click()
        else:
            self.settings.dark_theme.click()

    def _toggle_maximized(self) -> None:
        if self.isMaximized():
            self.showNormal()
        else:
            self.showMaximized()

    def _configure_editor_shortcuts(self, bindings: Mapping[str, str]) -> None:
        """Replace the six application-scoped editor bindings atomically."""

        expected = {
            "select",
            "pan",
            "undo",
            "redo",
            "preview",
            "exit_focus",
        }
        if set(bindings) != expected:
            raise ValueError("editor shortcut bindings are incomplete")
        sequences = {
            command_id: QtGui.QKeySequence(str(bindings[command_id]))
            for command_id in sorted(expected)
        }
        if any(sequence.isEmpty() for sequence in sequences.values()):
            raise ValueError("editor shortcut bindings must not be empty")
        portable = [
            sequence.toString(QtGui.QKeySequence.SequenceFormat.PortableText).casefold()
            for sequence in sequences.values()
        ]
        if len(portable) != len(set(portable)):
            raise ValueError("editor shortcut bindings must be unique")
        previous = self._editor_shortcuts
        replacements: dict[str, QtGui.QShortcut] = {}
        for command_id, sequence in sequences.items():
            shortcut = QtGui.QShortcut(sequence, self)
            shortcut.setContext(QtCore.Qt.ShortcutContext.WindowShortcut)
            shortcut.activated.connect(
                lambda value=command_id: self._activate_editor_shortcut(value)
            )
            replacements[command_id] = shortcut
        self._editor_shortcuts = replacements
        for shortcut in previous.values():
            shortcut.setEnabled(False)
            shortcut.deleteLater()

    @QtCore.Slot(str)
    def _activate_editor_shortcut(self, command_id: str) -> None:
        if self._application_model.state.navigation_id != "editor":
            return
        application = QtWidgets.QApplication.instance()
        if application is not None and application.activeModalWidget() is not None:
            return
        if command_id == "select":
            self.editor.select_tool_button.click()
        elif command_id == "pan":
            self.editor.pan_tool_button.click()
        elif command_id == "undo":
            if self._header_undo.isEnabled():
                self.editor.history_revoke_requested.emit()
        elif command_id == "redo":
            if self._header_redo.isEnabled():
                self.editor.history_reapply_requested.emit()
        elif command_id == "preview":
            if self.editor.rerender_button.isEnabled():
                self.editor.rerender_button.click()
        elif command_id == "exit_focus":
            self.editor.exit_canvas_focus()
        else:
            raise ValueError("unsupported editor shortcut command")

    def eventFilter(
        self,
        watched: QtCore.QObject,
        event: QtCore.QEvent,
    ) -> bool:  # noqa: N802
        if watched in self._window_drag_surfaces:
            if event.type() == QtCore.QEvent.Type.MouseButtonDblClick:
                mouse_event = event
                if (
                    isinstance(mouse_event, QtGui.QMouseEvent)
                    and mouse_event.button() == QtCore.Qt.MouseButton.LeftButton
                ):
                    self._toggle_maximized()
                    return True
            if event.type() == QtCore.QEvent.Type.MouseButtonPress:
                mouse_event = event
                if (
                    isinstance(mouse_event, QtGui.QMouseEvent)
                    and mouse_event.button() == QtCore.Qt.MouseButton.LeftButton
                ):
                    handle = self.windowHandle()
                    if handle is not None:
                        handle.startSystemMove()
                        return True
        return super().eventFilter(watched, event)

    def nativeEvent(
        self,
        event_type: bytes,
        message: int,
    ) -> tuple[bool, int]:  # noqa: N802
        """Retain native edge resizing while the prototype header owns chrome."""

        if os.name == "nt" and not self.isMaximized():
            try:
                import ctypes
                from ctypes import wintypes

                native_message = wintypes.MSG.from_address(int(message))
                if native_message.message == 0x0084:  # WM_NCHITTEST
                    packed = int(native_message.lParam)
                    global_x = ctypes.c_short(packed & 0xFFFF).value
                    global_y = ctypes.c_short((packed >> 16) & 0xFFFF).value
                    frame = wintypes.RECT()
                    get_window_rect = ctypes.windll.user32.GetWindowRect
                    get_window_rect.argtypes = (
                        wintypes.HWND,
                        ctypes.POINTER(wintypes.RECT),
                    )
                    get_window_rect.restype = wintypes.BOOL
                    if not get_window_rect(
                        native_message.hWnd,
                        ctypes.byref(frame),
                    ):
                        raise OSError(ctypes.get_last_error())
                    border = max(6, int(round(7 * self.devicePixelRatioF())))
                    hit = _windows_resize_hit_test(
                        global_x,
                        global_y,
                        (frame.left, frame.top, frame.right, frame.bottom),
                        border,
                    )
                    if hit:
                        return True, hit
            except (ImportError, TypeError, ValueError, OSError):
                pass
        return super().nativeEvent(event_type, message)

