    @staticmethod
    def _target_text_command_settled(state: Any) -> bool:
        """Ignore freshness while preserving all target command/draft gates."""

        return bool(
            not state.dirty
            and not state.busy
            and state.phase is not TargetTextEditorPhase.STALE
            and state.worker_command is None
        )

