    def _refresh_render_box_editor(self) -> None:
        model = self._render_box_model
        if model is None:
            if not self._selected_parent_id:
                self.editor.set_render_box_editor_state(
                    automatic_render_box=None,
                    automatic_hard_bounds=None,
                    user_render_box=None,
                    effective_render_box=None,
                    draft_render_box=None,
                    render_box_authority="unavailable",
                    render_required=False,
                    editing_enabled=False,
                    apply_enabled=False,
                    cancel_enabled=False,
                    restore_enabled=False,
                    busy=False,
                    status_text=(
                        "Select a render-required parent to edit the render box"
                    ),
                    status_tone=PresentationTone.MUTED.value,
                )
            self._refresh_font_role_editor()
            return
        state = model.state
        mutation_allowed = self._render_box_mutation_allowed()
        status_text = state.status_text
        status_tone = _RENDER_BOX_TONES[state.phase]
        if not state.busy and self._project_thread is not None:
            status_text = "Render-box editing is paused while another project opens."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and self._application_model.state.pipeline_busy:
            status_text = "Render-box editing is paused while a run is active."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and not self._active_project_matches_projection():
            status_text = "Reload the active project before editing the render box."
            status_tone = PresentationTone.WARNING.value
        elif not state.busy and not mutation_allowed:
            status_text = (
                "Resolve the active editor command before editing the render box."
            )
            status_tone = PresentationTone.WARNING.value
        self.editor.set_render_box_editor_state(
            automatic_render_box=state.selection.automatic_render_box,
            automatic_hard_bounds=state.selection.automatic_hard_bounds,
            user_render_box=state.selection.user_render_box,
            effective_render_box=state.selection.effective_render_box,
            draft_render_box=state.draft_render_box,
            render_box_authority=state.selection.render_box_authority,
            render_required=state.selection.render_required,
            editing_enabled=state.editing_enabled and mutation_allowed,
            apply_enabled=state.apply_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            restore_enabled=state.restore_enabled and mutation_allowed,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
        )
        self._refresh_font_role_editor()

