    def _start_outline_color_worker(
        self,
        command: RenderStyleOutlineColorWorkerCommand,
    ) -> None:
        if not isinstance(command, RenderStyleOutlineColorWorkerCommand):
            raise TypeError(
                "command must be RenderStyleOutlineColorWorkerCommand"
            )
        if self._outline_color_thread is not None:
            raise RuntimeError("a outline-color worker is already active")
        if not self._outline_color_mutation_allowed():
            raise RuntimeError("outline color is not currently editable")
        thread = QtCore.QThread(self)
        worker = RenderStyleOutlineColorWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_outline_color_busy)
        worker.receipt.connect(self._accept_outline_color_receipt)
        worker.stale.connect(self._accept_outline_color_stale)
        worker.failure.connect(self._accept_outline_color_failure)
        worker.cancelled.connect(self._accept_outline_color_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_outline_color_thread",
            worker_attribute="_outline_color_worker",
            on_settled=self._outline_color_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_outline_color_busy(self, value: object) -> None:
        if not isinstance(value, RenderStyleOutlineColorWorkerBusyState):
            raise TypeError(
                "busy signal must carry RenderStyleOutlineColorWorkerBusyState"
            )
        model = self._outline_color_model
        command = model.state.worker_command if model is not None else None
        if (
            model is None
            or command is None
            or command.page_id != value.page_id
            or command.parent_id != value.parent_id
        ):
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @staticmethod
    def _outline_color_edit_matches_command(
        edit: Any,
        command: RenderStyleOutlineColorWorkerCommand,
    ) -> bool:
        payload = dict(edit.payload)
        fields = payload.get("fields")
        if command.operation.value == "set":
            payload_matches = bool(
                command.outline_color is not None
                and set(payload) == {"fields"}
                and isinstance(fields, Mapping)
                and dict(fields) == {"outline_color": command.outline_color}
            )
            edit_operation = "set_fields"
        else:
            payload_matches = bool(
                command.outline_color is None
                and set(payload) == {"fields"}
                and isinstance(fields, tuple)
                and fields == ("outline_color",)
            )
            edit_operation = "restore_automatic"
        return bool(
            edit.domain is EditDomain.RENDER_STYLE
            and edit.operation == edit_operation
            and edit.page_id == command.page_id
            and edit.target.kind is EditTargetKind.PARENT
            and edit.target.parent_id == command.parent_id
            and not edit.target.artifact_id
            and not edit.target.edit_id
            and payload_matches
        )

    def _outline_color_receipt_matches_command(
        self,
        value: RenderStyleOutlineColorWorkerReceipt,
        model: RenderStyleOutlineColorEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        receipt = value.command_receipt
        if command is None:
            return False
        if command.operation.value == "set":
            after_matches = bool(
                command.outline_color is not None
                and receipt.after_outline_color == command.outline_color
                and receipt.after_outline_color_authority == "user"
            )
        else:
            after_matches = bool(
                command.outline_color is None
                and receipt.after_outline_color == receipt.automatic_outline_color
                and receipt.after_outline_color_authority == "automatic"
            )
        if state.selection.outline_color_authority == "unresolved":
            before_matches = bool(
                receipt.before_outline_color == receipt.automatic_outline_color
                and receipt.before_outline_color_authority == "automatic"
                and receipt.superseded_edit_id
            )
        else:
            before_matches = bool(
                receipt.before_outline_color
                == state.selection.effective_outline_color
                and receipt.before_outline_color_authority
                == state.selection.outline_color_authority
            )
        edit = receipt.edit
        commit = receipt.commit_receipt
        return bool(
            self._outline_color_edit_matches_command(edit, command)
            and receipt.command_id == edit.edit_id == commit.transaction_id
            and receipt.superseded_edit_id == edit.supersedes_edit_id
            and commit.page_id == command.page_id == edit.page_id
            and commit.edit_ids == (edit.edit_id,)
            and commit.artifact_revision_ids == ()
            and command.expected_effective_page_fingerprint
            == receipt.before_effective_page_fingerprint
            and receipt.automatic_outline_color
            == state.selection.automatic_outline_color
            and before_matches
            and after_matches
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(state.selection.project_path))
        )

    def _outline_color_receipt_matches_current(
        self,
        value: RenderStyleOutlineColorWorkerReceipt,
        model: RenderStyleOutlineColorEditorModel,
    ) -> bool:
        if not self._outline_color_receipt_matches_command(value, model):
            return False
        state = model.state
        command = state.worker_command
        if command is None or self._projection is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        project_record = value.project.get("project")
        returned_project_id = (
            str(project_record.get("project_id") or "")
            if isinstance(project_record, Mapping)
            else ""
        )
        try:
            current_parent = self._projection.page(command.page_id).parent(
                command.parent_id
            )
        except (KeyError, ValueError):
            return False
        if current_parent.outline_color_authority == "unresolved":
            unresolved_edit_ids = {
                edit_id
                for issue in current_parent.effective.issues
                if issue.kind is ProjectionIssueKind.INVALID_EFFECTIVE_VALUE
                and issue.reason
                == "render_style.outline_color_requires_opaque_rgb"
                for edit_id in issue.edit_ids
            }
            current_fill_matches = bool(
                current_parent.automatic_outline_color
                == receipt.automatic_outline_color
                and unresolved_edit_ids == {receipt.superseded_edit_id}
            )
        else:
            current_fill_matches = bool(
                current_parent.automatic_outline_color
                == receipt.automatic_outline_color
                and current_parent.effective_outline_color
                == receipt.before_outline_color
                and current_parent.outline_color_authority
                == receipt.before_outline_color_authority
            )
        return bool(
            current_fill_matches
            and self._selected_page_id == command.page_id
            and self._selected_parent_id == command.parent_id
            and active_path
            == os.path.normcase(os.path.abspath(command.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(
                os.path.abspath(application_project.project_path)
            )
            == active_path
            and value.projection.metadata.project_id == edit.project_id
            and returned_project_id == edit.project_id
        )

    @QtCore.Slot(object)
    def _accept_outline_color_receipt(self, value: object) -> None:
        if not isinstance(value, RenderStyleOutlineColorWorkerReceipt):
            raise TypeError(
                "receipt signal must carry RenderStyleOutlineColorWorkerReceipt"
            )
        model = self._outline_color_model
        if model is None or not self._outline_color_receipt_matches_current(
            value,
            model,
        ):
            if (
                model is not None
                and self._outline_color_receipt_matches_command(value, model)
            ):
                active_command = model.state.worker_command
                if active_command is not None:
                    model.accept_stale(
                        RenderStyleOutlineColorWorkerFailure(
                            code=(
                                RenderStyleOutlineColorWorkerFailureCode.SNAPSHOT_STALE
                            ),
                            stage=RenderStyleOutlineColorWorkerStage.COMPLETE,
                            project_path=active_command.project_path,
                            page_id=active_command.page_id,
                            parent_id=active_command.parent_id,
                            operation=active_command.operation,
                            outline_color=active_command.outline_color,
                            message=(
                                "The outline-color edit was saved, but the active "
                                "project changed. Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "A outline-color edit finished for a project that is no longer "
                "active. Reopen that project to inspect the saved edit.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        receipt = value.command_receipt
        selected_page = receipt.edit.page_id
        selected_parent = receipt.edit.target.parent_id
        self._project, self._projection = dict(value.project), value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "Outline color saved. Preview this page explicitly to render the change."
        )

    def _outline_color_event_matches_active(
        self,
        value: (
            RenderStyleOutlineColorWorkerFailure
            | RenderStyleOutlineColorCancelledReceipt
        ),
    ) -> bool:
        model = self._outline_color_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        return bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.operation is value.operation
            and command.outline_color == value.outline_color
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value.project_path))
        )

