    def _add_user_parent_mutation_allowed(self) -> bool:
        model = self._add_user_parent_model
        source_state = (
            self._source_text_model.state
            if self._source_text_model is not None
            else None
        )
        target_state = (
            self._target_text_model.state
            if self._target_text_model is not None
            else None
        )
        membership_state = (
            self._parent_membership_model.state
            if self._parent_membership_model is not None
            else None
        )
        geometry_state = (
            self._parent_geometry_model.state
            if self._parent_geometry_model is not None
            else None
        )
        reading_order_state = (
            self._reading_order_model.state
            if self._reading_order_model is not None
            else None
        )
        writing_mode_state = (
            self._writing_mode_model.state
            if self._writing_mode_model is not None
            else None
        )
        line_height_state = (
            self._line_height_model.state
            if self._line_height_model is not None
            else None
        )
        rotation_state = (
            self._rotation_model.state
            if self._rotation_model is not None
            else None
        )
        font_role_state = (
            self._font_role_model.state
            if self._font_role_model is not None
            else None
        )
        history_state = (
            self._edit_history_model.state
            if self._edit_history_model is not None
            else None
        )
        return bool(
            model is not None
            and model.state.editing_enabled
            and not self._application_model.state.pipeline_busy
            and self._project_thread is None
            and self._source_text_thread is None
            and self._target_text_thread is None
            and self._parent_membership_thread is None
            and self._parent_geometry_thread is None
            and self._reading_order_thread is None
            and self._writing_mode_thread is None
            and self._line_height_thread is None
            and self._rotation_thread is None
            and self._render_box_command_settled()
            and self._font_role_thread is None
            and self._font_weight_tier_command_settled()
            and self._fill_color_thread is None
            and self._outline_color_thread is None
            and self._outline_width_thread is None
            and self._preferred_size_thread is None
            and self._shadow_visibility_thread is None
            and self._add_user_parent_thread is None
            and self._edit_history_thread is None
            and (source_state is None or source_state.stable_for_run)
            and (
                target_state is None
                or self._target_text_command_settled(target_state)
            )
            and (membership_state is None or membership_state.stable_for_run)
            and (geometry_state is None or geometry_state.stable_for_run)
            and (
                reading_order_state is None
                or reading_order_state.stable_for_run
            )
            and (
                writing_mode_state is None
                or writing_mode_state.stable_for_run
            )
            and (
                line_height_state is None
                or line_height_state.stable_for_run
            )
            and (rotation_state is None or rotation_state.stable_for_run)
            and (font_role_state is None or font_role_state.stable_for_run)
            and self._font_role_command_settled()
            and self._fill_color_command_settled()
            and self._outline_color_command_settled()
            and (history_state is None or history_state.stable_for_run)
            and self._active_project_matches_projection()
        )

    @QtCore.Slot(object)
    def _set_add_user_parent_role(self, role: object) -> None:
        model = self._add_user_parent_model
        if model is None or not self._add_user_parent_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before changing Add Parent.",
                warning=True,
            )
            return
        try:
            model.set_draft_role(role if isinstance(role, str) else None)
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot(object)
    def _set_add_user_parent_workflow_area(self, value: object) -> None:
        model = self._add_user_parent_model
        if model is None or not self._add_user_parent_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before changing Add Parent.",
                warning=True,
            )
            return
        try:
            model.set_draft_workflow_area(value)  # type: ignore[arg-type]
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _cancel_add_user_parent_draft(self) -> None:
        model = self._add_user_parent_model
        if model is None:
            return
        if self._add_user_parent_thread is not None:
            worker = self._add_user_parent_worker
            if worker is not None and model.state.cancellation_enabled:
                if worker.request_cancel():
                    self._set_notice(
                        "Cancelling Add Parent before persistence…"
                    )
                return
            self._set_notice(
                "Add Parent persistence has started and can no longer be cancelled.",
                warning=True,
            )
            return
        try:
            model.cancel_draft()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _apply_add_user_parent_draft(self) -> None:
        model = self._add_user_parent_model
        if model is None or not self._add_user_parent_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before adding a parent.",
                warning=True,
            )
            return
        try:
            state = model.state
            if state.parent_id or state.root_id:
                parent_id, root_id = state.parent_id, state.root_id
            else:
                parent_id, root_id = create_user_parent_identity()
            command = model.begin_add(parent_id=parent_id, root_id=root_id)
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_add_user_parent_worker(command)

    def _start_add_user_parent_worker(
        self,
        command: AddUserParentWorkerCommand,
    ) -> None:
        if not isinstance(command, AddUserParentWorkerCommand):
            raise TypeError("command must be AddUserParentWorkerCommand")
        if self._add_user_parent_thread is not None:
            raise RuntimeError("an Add Parent worker is already active")
        model = self._add_user_parent_model
        if model is None or model.state.worker_command != command:
            raise RuntimeError("Add Parent command is not the active fixed draft")
        thread = QtCore.QThread(self)
        worker = AddUserParentWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_add_user_parent_busy)
        worker.receipt.connect(self._accept_add_user_parent_receipt)
        worker.stale.connect(self._accept_add_user_parent_stale)
        worker.failure.connect(self._accept_add_user_parent_failure)
        worker.cancelled.connect(self._accept_add_user_parent_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_add_user_parent_thread",
            worker_attribute="_add_user_parent_worker",
            on_settled=self._add_user_parent_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_add_user_parent_busy(self, value: object) -> None:
        if not isinstance(value, AddUserParentWorkerBusyState):
            raise TypeError(
                "busy signal must carry AddUserParentWorkerBusyState"
            )
        model = self._add_user_parent_model
        if model is None or not self._add_user_parent_event_matches_active(value):
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _add_user_parent_receipt_matches_command(
        self,
        value: AddUserParentWorkerReceipt,
        model: AddUserParentEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        if command is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        commit = receipt.commit_receipt
        return bool(
            receipt.parent_id == command.parent_id
            and receipt.root_id == command.root_id
            and receipt.role == command.role
            and receipt.workflow_area_bbox == command.workflow_area_bbox
            and receipt.before_effective_page_fingerprint
            == command.expected_effective_page_fingerprint
            and receipt.before_hierarchy_revision_id
            == command.expected_hierarchy_revision_id
            and receipt.before_hierarchy_fingerprint
            == command.expected_hierarchy_fingerprint
            and receipt.command_id == edit.edit_id == commit.transaction_id
            and commit.page_id == command.page_id == edit.page_id
            and commit.edit_ids == (edit.edit_id,)
            and commit.artifact_revision_ids == ()
            and edit.target.kind is EditTargetKind.PARENT
            and edit.target.parent_id == command.parent_id
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(state.selection.project_path))
        )

    def _add_user_parent_receipt_matches_current(
        self,
        value: AddUserParentWorkerReceipt,
        model: AddUserParentEditorModel,
    ) -> bool:
        if not self._add_user_parent_receipt_matches_command(value, model):
            return False
        command = model.state.worker_command
        if command is None or self._projection is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        project_record = value.project.get("project")
        returned_project_id = (
            str(project_record.get("project_id") or "")
            if isinstance(project_record, Mapping)
            else ""
        )
        try:
            current_page = self._projection.page(command.page_id)
        except (KeyError, ValueError):
            return False
        try:
            current_page.parent(command.parent_id)
        except KeyError:
            identity_is_new = True
        except ValueError:
            return False
        else:
            identity_is_new = False
        return bool(
            identity_is_new
            and self._selected_page_id == command.page_id
            and current_page.effective.effective_fingerprint
            == command.expected_effective_page_fingerprint
            and current_page.hierarchy_revision.revision_id
            == command.expected_hierarchy_revision_id
            and current_page.hierarchy_revision.fingerprint
            == command.expected_hierarchy_fingerprint
            and active_path
            == os.path.normcase(os.path.abspath(command.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(os.path.abspath(application_project.project_path))
            == active_path
            and value.projection.metadata.project_id == edit.project_id
            and returned_project_id == edit.project_id
        )

    @QtCore.Slot(object)
    def _accept_add_user_parent_receipt(self, value: object) -> None:
        if not isinstance(value, AddUserParentWorkerReceipt):
            raise TypeError(
                "receipt signal must carry AddUserParentWorkerReceipt"
            )
        model = self._add_user_parent_model
        if model is None or not self._add_user_parent_receipt_matches_current(
            value,
            model,
        ):
            if (
                model is not None
                and self._add_user_parent_receipt_matches_command(value, model)
            ):
                command = model.state.worker_command
                if command is not None:
                    model.accept_stale(
                        AddUserParentWorkerFailure(
                            code=AddUserParentWorkerFailureCode.SNAPSHOT_STALE,
                            stage=AddUserParentWorkerStage.COMPLETE,
                            project_path=command.project_path,
                            page_id=command.page_id,
                            parent_id=command.parent_id,
                            root_id=command.root_id,
                            role=command.role,
                            workflow_area_bbox=command.workflow_area_bbox,
                            message=(
                                "Add Parent was saved, but the active project changed. "
                                "Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "Add Parent finished for a project that is no longer active. "
                "Reopen that project to inspect the saved parent.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        receipt = value.command_receipt
        # The committed source parent no longer exists in the new hierarchy.
        # Drop its editor model before synchronously selecting the first child;
        # otherwise the still-owned worker thread blocks that receipt-driven
        # selection and leaves presentation dependent on a later zero-timer.
        self._split_parent_model = None
        self._project, self._projection = dict(value.project), value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = receipt.edit.page_id
        self._selected_parent_id = receipt.parent_id
        self.select_page(receipt.edit.page_id)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "User parent added as pending. Complete its explicit required "
            "revisions, or remove it through History; Start and Preview remain unavailable."
        )

    def _add_user_parent_event_matches_active(
        self,
        value: (
            AddUserParentWorkerBusyState
            | AddUserParentWorkerFailure
            | AddUserParentCancelledReceipt
        ),
    ) -> bool:
        model = self._add_user_parent_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        value_path = getattr(value, "project_path", command.project_path)
        return bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.root_id == value.root_id
            and command.role == value.role
            and command.workflow_area_bbox == value.workflow_area_bbox
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value_path))
        )

    @QtCore.Slot(object)
    def _accept_add_user_parent_stale(self, value: object) -> None:
        if not isinstance(value, AddUserParentWorkerFailure):
            raise TypeError(
                "stale signal must carry AddUserParentWorkerFailure"
            )
        if not self._add_user_parent_event_matches_active(value):
            return
        model = self._add_user_parent_model
        if model is None:
            return
        model.accept_stale(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

    @QtCore.Slot(object)
    def _accept_add_user_parent_failure(self, value: object) -> None:
        if not isinstance(value, AddUserParentWorkerFailure):
            raise TypeError(
                "failure signal must carry AddUserParentWorkerFailure"
            )
        if not self._add_user_parent_event_matches_active(value):
            return
        model = self._add_user_parent_model
        if model is None:
            return
        model.accept_failure(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

    @QtCore.Slot(object)
    def _accept_add_user_parent_cancelled(self, value: object) -> None:
        if not isinstance(value, AddUserParentCancelledReceipt):
            raise TypeError(
                "cancelled signal must carry AddUserParentCancelledReceipt"
            )
        if not self._add_user_parent_event_matches_active(value):
            return
        model = self._add_user_parent_model
        if model is None:
            return
        model.accept_cancelled(value)
        self._refresh_target_text_editor()
