    @QtCore.Slot()
    def _translation_revision_thread_finished(self) -> None:
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _refresh_translation_revision_editor(self) -> None:
        model = self._translation_revision_model
        if model is None:
            if (
                self._projection is None
                or not self._selected_page_id
                or not self._selected_parent_id
            ):
                return
            try:
                parent = self._projection.page(self._selected_page_id).parent(
                    self._selected_parent_id
                )
            except (KeyError, ValueError):
                return
            if parent.origin is not ParentOrigin.USER:
                return
            artifact = parent.selected_model_translation_revision
            authority = {
                "unavailable": "unavailable",
                "translation_revision": "model",
                "mapped_automatic": "mapped",
                "user": "user",
            }.get(parent.effective.target_authority, "unavailable")
            self.editor.set_translation_revision_state(
                automatic_target_text=None,
                model_revision_id=(artifact.revision_id if artifact else None),
                model_revision_text=(artifact.target_text if artifact else None),
                model_provider=(
                    f"{artifact.provider.provider_kind} ({artifact.provider.profile_id})"
                    if artifact
                    else None
                ),
                model_id=(artifact.provider.model_id if artifact else None),
                user_target_text=parent.user_target_text,
                effective_target_text=parent.effective.target_text,
                effective_target_authority=authority,
                rerun_enabled=False,
                cancel_enabled=False,
                busy=False,
                status_text=(
                    self._translation_revision_unavailable_reason
                    or "Retranslate Parent is unavailable for this selection."
                ),
                status_tone=PresentationTone.WARNING.value,
                mapped_pipeline_target_text=(
                    parent.mapped_pipeline_target_text
                ),
            )
            return
        state = model.state
        selection = state.selection
        artifact = selection.model_translation_revision
        status_text = state.message
        status_tone = _TRANSLATION_REVISION_TONES[state.phase]
        if not state.busy and state.phase not in {
            TranslationRevisionPhase.FAILED,
            TranslationRevisionPhase.STALE,
            TranslationRevisionPhase.UNAVAILABLE,
            TranslationRevisionPhase.SUCCEEDED,
        }:
            if self._project_thread is not None:
                status_text = (
                    "Retranslate Parent is paused while another project opens."
                )
                status_tone = PresentationTone.MUTED.value
            elif self._application_model.state.pipeline_busy:
                status_text = "Retranslate Parent is paused while a run is active."
                status_tone = PresentationTone.MUTED.value
            elif not self._active_project_matches_projection():
                status_text = "Reload the active project before Retranslate Parent."
                status_tone = PresentationTone.WARNING.value
            elif not self._translation_revision_mutation_allowed():
                status_text = (
                    "Resolve the active editor command before Retranslate Parent."
                )
                status_tone = PresentationTone.WARNING.value
        self.editor.set_translation_revision_state(
            automatic_target_text=None,
            model_revision_id=(artifact.revision_id if artifact else None),
            model_revision_text=(artifact.target_text if artifact else None),
            model_provider=(
                f"{selection.provider.provider_kind} ({selection.provider.profile_id})"
                if artifact
                else None
            ),
            model_id=(selection.provider.model_id if artifact else None),
            user_target_text=selection.user_target_text,
            effective_target_text=selection.effective_target_text,
            effective_target_authority={
                "unavailable": "unavailable",
                "translation_revision": "model",
                "mapped_automatic": "mapped",
                "user": "user",
            }[selection.effective_target_authority],
            rerun_enabled=(
                state.run_enabled and self._translation_revision_mutation_allowed()
            ),
            cancel_enabled=state.cancel_enabled,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
        )

