    @QtCore.Slot(str)
    def _set_source_text_draft(self, text: str) -> None:
        model = self._source_text_model
        if model is None or not self._source_text_mutation_allowed():
            return
        try:
            model.set_draft(text)
        except RuntimeError:
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _cancel_source_text_draft(self) -> None:
        model = self._source_text_model
        if model is None:
            return
        try:
            model.cancel_draft()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _apply_source_text_draft(self) -> None:
        model = self._source_text_model
        if model is None or not self._source_text_mutation_allowed():
            return
        try:
            command = model.begin_replace()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_source_text_worker(command)

    @QtCore.Slot()
    def _restore_automatic_source_text(self) -> None:
        model = self._source_text_model
        if model is None or not self._source_text_mutation_allowed():
            return
        try:
            command = model.begin_restore()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_source_text_worker(command)

    def _start_source_text_worker(self, command: SourceTextWorkerCommand) -> None:
        if not isinstance(command, SourceTextWorkerCommand):
            raise TypeError("command must be SourceTextWorkerCommand")
        if not self._source_text_mutation_allowed():
            raise RuntimeError("a source-text worker is already active")
        thread = QtCore.QThread(self)
        worker = SourceTextWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_source_text_busy)
        worker.receipt.connect(self._accept_source_text_receipt)
        worker.stale.connect(self._accept_source_text_stale)
        worker.failure.connect(self._accept_source_text_failure)
        worker.cancelled.connect(self._accept_source_text_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_source_text_thread",
            worker_attribute="_source_text_worker",
            on_settled=self._source_text_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_source_text_busy(self, value: object) -> None:
        if not isinstance(value, SourceTextWorkerBusyState):
            raise TypeError("busy signal must carry SourceTextWorkerBusyState")
        model = self._source_text_model
        command = model.state.worker_command if model is not None else None
        if (
            model is None
            or command is None
            or command.page_id != value.page_id
            or command.parent_id != value.parent_id
        ):
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()

    @staticmethod
    def _source_text_edit_matches_command(
        edit: Any,
        command: SourceTextWorkerCommand,
    ) -> bool:
        expected_payload = (
            {"text": command.text}
            if command.operation.value == "replace"
            else {}
        )
        return bool(
            edit.domain is EditDomain.SOURCE_TEXT
            and edit.operation == command.operation.value
            and edit.page_id == command.page_id
            and edit.target.parent_id == command.parent_id
            and dict(edit.payload) == expected_payload
        )

    def _source_text_receipt_matches_command(
        self,
        value: SourceTextWorkerReceipt,
        model: SourceTextEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        receipt = value.command_receipt
        return bool(
            command is not None
            and self._source_text_edit_matches_command(receipt.edit, command)
            and command.expected_effective_page_fingerprint
            == receipt.before_effective_page_fingerprint
            and receipt.before_source_text
            == state.selection.effective_source_text
            and receipt.before_source_authority
            == state.selection.source_authority
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(state.selection.project_path))
        )

    def _source_text_receipt_matches_current(
        self,
        value: SourceTextWorkerReceipt,
        model: SourceTextEditorModel,
    ) -> bool:
        if not self._source_text_receipt_matches_command(value, model):
            return False
        state = model.state
        command = state.worker_command
        if command is None or self._projection is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        try:
            current_parent = (
                self._projection.page(command.page_id)
                .parent(command.parent_id)
                .effective
            )
        except (KeyError, ValueError):
            return False
        return bool(
            receipt.before_target_text == current_parent.target_text
            and receipt.before_target_authority == current_parent.target_authority
            and receipt.before_target_freshness
            is current_parent.target_freshness
            and active_path
            == os.path.normcase(os.path.abspath(command.project_path))
            and active_path
            == os.path.normcase(os.path.abspath(value.projection.metadata.project_path))
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(os.path.abspath(application_project.project_path))
            == active_path
            and value.projection.metadata.project_id == edit.project_id
        )

    @QtCore.Slot(object)
    def _accept_source_text_receipt(self, value: object) -> None:
        if not isinstance(value, SourceTextWorkerReceipt):
            raise TypeError("receipt signal must carry SourceTextWorkerReceipt")
        model = self._source_text_model
        if model is None or not self._source_text_receipt_matches_current(
            value,
            model,
        ):
            if (
                model is not None
                and self._source_text_receipt_matches_command(value, model)
            ):
                active_command = model.state.worker_command
                if active_command is not None:
                    model.accept_stale(
                        SourceTextWorkerFailure(
                            code=SourceTextWorkerFailureCode.SNAPSHOT_STALE,
                            stage=SourceTextWorkerStage.COMPLETE,
                            project_path=active_command.project_path,
                            page_id=active_command.page_id,
                            parent_id=active_command.parent_id,
                            operation=active_command.operation,
                            text=active_command.text,
                            message=(
                                "The source edit was saved, but the active project "
                                "changed. Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "A source-text edit finished for a project that is no longer "
                "active. Reopen that project to inspect the saved edit.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        receipt = value.command_receipt
        selected_page = receipt.edit.page_id
        selected_parent = receipt.edit.target.parent_id
        self._project, self._projection = dict(value.project), value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        if receipt.after_target_freshness is TargetFreshness.STALE:
            self._set_notice(
                "Source text saved. Resolve the stale target explicitly before "
                "Preview or Start.",
                warning=True,
            )
        else:
            self._set_notice("Source text saved. Preview remains explicit.")

    def _source_text_event_matches_active(
        self,
        value: SourceTextWorkerFailure | SourceTextCancelledReceipt,
    ) -> bool:
        model = self._source_text_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        matches = bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.operation is value.operation
            and command.text == value.text
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value.project_path))
        )
        receipt = getattr(value, "command_receipt", None)
        return bool(
            matches
            and (
                receipt is None
                or (
                    self._source_text_edit_matches_command(receipt.edit, command)
                    and command.expected_effective_page_fingerprint
                    == receipt.before_effective_page_fingerprint
                )
            )
        )

    @QtCore.Slot(object)
    def _accept_source_text_stale(self, value: object) -> None:
        if not isinstance(value, SourceTextWorkerFailure):
            raise TypeError("stale signal must carry SourceTextWorkerFailure")
        if not self._source_text_event_matches_active(value):
            return
        model = self._source_text_model
        if model is None:
            return
        model.accept_stale(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

