    def _start_target_text_worker(self, command: TargetTextWorkerCommand) -> None:
        if not isinstance(command, TargetTextWorkerCommand):
            raise TypeError("command must be TargetTextWorkerCommand")
        if not self._target_text_mutation_allowed():
            raise RuntimeError("a target-text worker is already active")
        thread = QtCore.QThread(self)
        worker = TargetTextWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_target_text_busy)
        worker.receipt.connect(self._accept_target_text_receipt)
        worker.stale.connect(self._accept_target_text_stale)
        worker.failure.connect(self._accept_target_text_failure)
        worker.cancelled.connect(self._accept_target_text_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_target_text_thread",
            worker_attribute="_target_text_worker",
            on_settled=self._target_text_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_target_text_busy(self, value: object) -> None:
        if not isinstance(value, TargetTextWorkerBusyState):
            raise TypeError("busy signal must carry TargetTextWorkerBusyState")
        model = self._target_text_model
        if model is None:
            return
        if model.state.worker_command is not None:
            model.accept_busy(value)
            self._refresh_target_text_editor()

    @QtCore.Slot(object)
    def _accept_target_text_receipt(self, value: object) -> None:
        if not isinstance(value, TargetTextWorkerReceipt):
            raise TypeError("receipt signal must carry TargetTextWorkerReceipt")
        model = self._target_text_model
        if model is None or not self._target_text_receipt_matches_current(value, model):
            if model is not None:
                active_command = model.state.worker_command
                if (
                    active_command is not None
                    and active_command.command_id
                    == value.command_receipt.command_id
                ):
                    model.accept_stale(
                        TargetTextWorkerFailure(
                            code=TargetTextWorkerFailureCode.SNAPSHOT_STALE,
                            stage=TargetTextWorkerStage.COMPLETE,
                            project_path=active_command.project_path,
                            page_id=active_command.page_id,
                            parent_id=active_command.parent_id,
                            command_id=active_command.command_id,
                            message=(
                                "The edit was saved, but the active project changed. "
                                "Reload the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "A target-text edit finished for a project that is no longer active. "
                "Reopen that project to inspect the saved edit.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        selected_page = value.command_receipt.edit.page_id
        selected_parent = value.command_receipt.edit.target.parent_id
        self._project = dict(value.project)
        self._projection = value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "Target text saved. Preview this page explicitly to update rendered output."
        )

    def _target_text_receipt_matches_current(
        self,
        value: TargetTextWorkerReceipt,
        model: TargetTextEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        edit = value.command_receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        if command is None:
            return False
        expected_payload: dict[str, Any] = {}
        if command.operation.value == "replace":
            expected_payload = {
                "text": command.text,
                "source_fingerprint": value.command_receipt.source_fingerprint,
            }
        if command.revision_base is not None:
            expected_payload["revision_base"] = command.revision_base.to_dict()
        if command.source_evidence_base is not None:
            expected_payload["source_evidence_base"] = (
                command.source_evidence_base.to_dict()
            )
        projected_parent = value.projection.page(edit.page_id).parent(
            edit.target.parent_id
        )
        return bool(
            command.command_id == value.command_receipt.command_id
            and command.page_id == edit.page_id
            and command.parent_id == edit.target.parent_id
            and edit.domain is EditDomain.TARGET_TEXT
            and command.operation.value == edit.operation
            and dict(edit.payload) == expected_payload
            and command.revision_base == state.selection.revision_base
            and projected_parent.target_text_revision_base
            == command.revision_base
            and command.source_evidence_base
            == state.selection.source_evidence_base
            and projected_parent.effective.source_evidence_mapping
            == command.source_evidence_base
            and command.expected_effective_page_fingerprint
            == value.command_receipt.before_effective_page_fingerprint
            and value.command_receipt.before_target_text
            == state.selection.effective_target_text
            and value.command_receipt.before_target_authority
            == state.selection.target_authority
            and active_path
            == os.path.normcase(os.path.abspath(state.selection.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(os.path.abspath(application_project.project_path))
            == active_path
            and value.projection.metadata.project_id == edit.project_id
        )

