    def _selected_parent_is_user_authored(self) -> bool:
        if (
            self._projection is None
            or not self._selected_page_id
            or not self._selected_parent_id
        ):
            return False
        try:
            parent = self._projection.page(self._selected_page_id).parent(
                self._selected_parent_id
            )
        except (KeyError, ValueError):
            return False
        return parent.origin is ParentOrigin.USER

    def _refresh_source_text_editor(self) -> None:
        model = self._source_text_model
        if model is None:
            selected_user_parent = self._selected_parent_is_user_authored()
            self.editor.set_source_text_editor_state(
                draft_text="",
                editing_enabled=False,
                apply_enabled=False,
                cancel_enabled=False,
                restore_enabled=False,
                status_text=(
                    "Source text editing is unavailable for this selected user "
                    "parent. The selected model OCR revision is authoritative; "
                    "use Rerun OCR or History explicitly."
                    if selected_user_parent
                    else "Select a parent to edit source text"
                ),
                status_tone=PresentationTone.MUTED.value,
                history_identity="",
            )
            return
        state = model.state
        mutation_allowed = self._source_text_mutation_allowed()
        status_text = state.status_text
        status_tone = _SOURCE_TEXT_TONES[state.phase]
        target_state = (
            self._target_text_model.state
            if self._target_text_model is not None
            else None
        )
        membership_state = (
            self._parent_membership_model.state
            if self._parent_membership_model is not None
            else None
        )
        geometry_state = (
            self._parent_geometry_model.state
            if self._parent_geometry_model is not None
            else None
        )
        reading_order_state = (
            self._reading_order_model.state
            if self._reading_order_model is not None
            else None
        )
        history_state = (
            self._edit_history_model.state
            if self._edit_history_model is not None
            else None
        )
        if not state.busy and self._project_thread is not None:
            status_text = "Source editing is paused while another project opens."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and not self._active_project_matches_projection():
            status_text = "Reload the active project before editing source text."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and history_state is not None
            and not history_state.stable_for_run
        ):
            status_text = (
                "Reload the active project before editing source text."
                if history_state.stale
                else "Wait for the edit-history action before editing source text."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and target_state is not None
            and not self._target_text_command_settled(target_state)
        ):
            status_text = (
                "Reload the selected parent before editing source text."
                if target_state.phase is TargetTextEditorPhase.STALE
                else "Apply or Cancel the target-text draft before editing source text."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and membership_state is not None
            and not membership_state.stable_for_run
        ):
            status_text = "Reload the selected parent before editing source text."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and geometry_state is not None
            and not geometry_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing source text."
                if geometry_state.stale
                else "Apply or Cancel the geometry draft before editing source text."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and reading_order_state is not None
            and not reading_order_state.stable_for_run
        ):
            status_text = (
                "Reload the selected page before editing source text."
                if reading_order_state.stale
                else "Apply or Cancel the reading-order draft before editing source text."
            )
            status_tone = PresentationTone.WARNING.value
        self.editor.set_source_text_editor_state(
            draft_text=state.draft_text,
            editing_enabled=state.editing_enabled and mutation_allowed,
            apply_enabled=state.apply_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            restore_enabled=state.restore_enabled and mutation_allowed,
            status_text=status_text,
            status_tone=status_tone,
            history_identity="\0".join(
                (
                    os.path.normcase(os.path.abspath(state.selection.project_path)),
                    state.selection.page_id,
                    state.selection.parent_id,
                    "source_text",
                )
            ),
        )

    def _translation_revision_freshness(self) -> str | None:
        model = self._translation_revision_model
        if model is None or not model.state.selection.source_current:
            return None
        selection = model.state.selection
        if selection.translation_current:
            return "Translation current — later revisions required"
        if selection.translation_runnable:
            return "Translation required — source current"
        return None

    def _refresh_target_text_editor(self) -> None:
        self._refresh_source_text_editor()
        self._refresh_ocr_revision_editor()
        self._refresh_translation_revision_editor()
        model = self._target_text_model
        if model is None:
            selected_user_parent = self._selected_parent_is_user_authored()
            translation_current = bool(
                selected_user_parent
                and self._translation_revision_model is not None
                and self._translation_revision_model.state.selection.translation_current
            )
            self.editor.set_target_text_editor_state(
                draft_text="",
                editing_enabled=False,
                apply_enabled=False,
                cancel_enabled=False,
                restore_enabled=False,
                status_text=(
                    "Target text editing is unavailable for this selected user "
                    "parent. The selected model translation revision is current; "
                    "later owner revisions remain explicit."
                    if translation_current
                    else (
                        "Target text editing is unavailable for this selected user "
                        "parent until a selected model translation revision is "
                        "current. Use Retranslate Parent explicitly."
                        if selected_user_parent
                        else "Select a parent to edit target text"
                    )
                ),
                status_tone=PresentationTone.MUTED.value,
                history_identity="",
                freshness=self._translation_revision_freshness(),
                restore_selected_model_translation=selected_user_parent,
            )
            self._refresh_parent_membership_editor()
            self._refresh_shadow_visibility_editor()
            return
        state = model.state
        mutation_allowed = self._target_text_mutation_allowed()
        status_text = state.message
        status_tone = (
            PresentationTone.WARNING.value
            if state.selection.target_freshness is TargetFreshness.STALE
            else _TARGET_TEXT_TONES[state.phase]
        )
        source_state = (
            self._source_text_model.state
            if self._source_text_model is not None
            else None
        )
        membership_state = (
            self._parent_membership_model.state
            if self._parent_membership_model is not None
            else None
        )
        geometry_state = (
            self._parent_geometry_model.state
            if self._parent_geometry_model is not None
            else None
        )
        reading_order_state = (
            self._reading_order_model.state
            if self._reading_order_model is not None
            else None
        )
        history_state = (
            self._edit_history_model.state
            if self._edit_history_model is not None
            else None
        )
        if not state.busy and self._project_thread is not None:
            status_text = "Editing paused while another project opens."
        elif not state.busy and self._ocr_revision_thread is not None:
            status_text = "Wait for the active OCR revision before editing target text."
        elif not state.busy and self._translation_revision_thread is not None:
            status_text = (
                "Wait for the active translation revision before editing target text."
            )
        elif not state.busy and not self._active_project_matches_projection():
            status_text = "Reload the active project before editing."
        elif (
            not state.busy
            and history_state is not None
            and not history_state.stable_for_run
        ):
            status_text = (
                "Reload the active project before editing target text."
                if history_state.stale
                else "Wait for the edit-history action before editing target text."
            )
        elif not state.busy and source_state is not None and not source_state.stable_for_run:
            status_text = (
                "Reload the selected parent before editing target text."
                if source_state.stale
                else "Apply or Cancel the source-text draft before editing target text."
            )
        elif (
            not state.busy
            and membership_state is not None
            and not membership_state.stable_for_run
        ):
            status_text = "Reload the selected parent before editing target text."
        elif (
            not state.busy
            and geometry_state is not None
            and not geometry_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing target text."
                if geometry_state.stale
                else "Apply or Cancel the geometry draft before editing target text."
            )
        elif (
            not state.busy
            and reading_order_state is not None
            and not reading_order_state.stable_for_run
        ):
            status_text = (
                "Reload the selected page before editing target text."
                if reading_order_state.stale
                else "Apply or Cancel the reading-order draft before editing target text."
            )
        self.editor.set_target_text_editor_state(
            draft_text=state.draft_text,
            editing_enabled=state.editing_enabled and mutation_allowed,
            apply_enabled=state.apply_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            restore_enabled=state.restore_enabled and mutation_allowed,
            keep_existing_enabled=(
                state.keep_existing_enabled and mutation_allowed
            ),
            freshness=(
                self._translation_revision_freshness()
                or state.selection.target_freshness.value.title()
            ),
            status_text=status_text,
            status_tone=status_tone,
            restore_selected_model_translation=state.revision_backed,
            restore_mapped_pipeline_translation=state.mapped_pipeline_backed,
            history_identity="\0".join(
                (
                    os.path.normcase(
                        os.path.abspath(state.selection.project_path)
                    ),
                    state.selection.page_id,
                    state.selection.parent_id,
                    "target_text",
                )
            ),
        )
        self._refresh_parent_membership_editor()
        self._refresh_shadow_visibility_editor()

    @QtCore.Slot(bool)
    def _set_selected_parent_excluded(self, desired_excluded: bool) -> None:
        model = self._parent_membership_model
        if model is None or not self._parent_membership_mutation_allowed():
            return
        try:
            command = model.begin_set_excluded(bool(desired_excluded))
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_parent_membership_worker(command)

    def _start_parent_membership_worker(
        self,
        command: ParentMembershipWorkerCommand,
    ) -> None:
        if not isinstance(command, ParentMembershipWorkerCommand):
            raise TypeError("command must be ParentMembershipWorkerCommand")
        if not self._parent_membership_mutation_allowed():
            raise RuntimeError("a selected-parent command is already active")
        thread = QtCore.QThread(self)
        worker = ParentMembershipWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_parent_membership_busy)
        worker.receipt.connect(self._accept_parent_membership_receipt)
        worker.stale.connect(self._accept_parent_membership_stale)
        worker.failure.connect(self._accept_parent_membership_failure)
        worker.cancelled.connect(self._accept_parent_membership_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_parent_membership_thread",
            worker_attribute="_parent_membership_worker",
            on_settled=self._parent_membership_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_parent_membership_busy(self, value: object) -> None:
        if not isinstance(value, ParentMembershipWorkerBusyState):
            raise TypeError(
                "busy signal must carry ParentMembershipWorkerBusyState"
            )
        model = self._parent_membership_model
        if model is None or model.state.worker_command is None:
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()

    @QtCore.Slot(object)
    def _accept_parent_membership_receipt(self, value: object) -> None:
        if not isinstance(value, ParentMembershipWorkerReceipt):
            raise TypeError(
                "receipt signal must carry ParentMembershipWorkerReceipt"
            )
        model = self._parent_membership_model
        if model is None or not self._parent_membership_receipt_matches_current(
            value,
            model,
        ):
            if model is not None:
                active_command = model.state.worker_command
                edit = value.command_receipt.edit
                if (
                    active_command is not None
                    and active_command.page_id == edit.page_id
                    and active_command.parent_id == edit.target.parent_id
                    and active_command.operation.value == edit.operation
                    and active_command.expected_effective_page_fingerprint
                    == value.command_receipt.before_effective_page_fingerprint
                ):
                    model.accept_stale(
                        ParentMembershipWorkerFailure(
                            code=(
                                ParentMembershipWorkerFailureCode.SNAPSHOT_STALE
                            ),
                            stage=ParentMembershipWorkerStage.COMPLETE,
                            project_path=active_command.project_path,
                            page_id=active_command.page_id,
                            parent_id=active_command.parent_id,
                            operation=active_command.operation,
                            message=(
                                "The membership edit was saved, but the active "
                                "project changed. Reload the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "A parent-membership edit finished for a project that is no longer "
                "active. Reopen that project to inspect the saved edit.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        selected_page = value.command_receipt.edit.page_id
        selected_parent = value.command_receipt.edit.target.parent_id
        self._project = dict(value.project)
        self._projection = value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        verb = "excluded" if value.command_receipt.after_excluded else "restored"
        cleaned_state = value.projection.page(selected_page).cleaned_artifact_state
        if cleaned_state.value == "valid":
            notice = (
                f"Parent {verb}. Preview this page explicitly to update rendered "
                "output."
            )
        else:
            notice = (
                f"Parent {verb}. The selected cleaned base is {cleaned_state.value}; "
                "review cleanup before previewing this hierarchy."
            )
        self._set_notice(notice, warning=cleaned_state.value != "valid")

    def _parent_membership_receipt_matches_current(
        self,
        value: ParentMembershipWorkerReceipt,
        model: ParentMembershipEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        edit = value.command_receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        return bool(
            command is not None
            and command.page_id == edit.page_id
            and command.parent_id == edit.target.parent_id
            and command.operation.value == edit.operation
            and command.expected_effective_page_fingerprint
            == value.command_receipt.before_effective_page_fingerprint
            and active_path
            == os.path.normcase(os.path.abspath(state.selection.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(os.path.abspath(application_project.project_path))
            == active_path
            and value.projection.metadata.project_id == edit.project_id
        )

    def _parent_membership_event_matches_active(
        self,
        value: ParentMembershipWorkerFailure | ParentMembershipCancelledReceipt,
    ) -> bool:
        model = self._parent_membership_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        return bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.operation is value.operation
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value.project_path))
        )

    @QtCore.Slot(object)
    def _accept_parent_membership_stale(self, value: object) -> None:
        if not isinstance(value, ParentMembershipWorkerFailure):
            raise TypeError(
                "stale signal must carry ParentMembershipWorkerFailure"
            )
        if not self._parent_membership_event_matches_active(value):
            return
        model = self._parent_membership_model
        if model is None:
            return
        model.accept_stale(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

    @QtCore.Slot(object)
    def _accept_parent_membership_failure(self, value: object) -> None:
        if not isinstance(value, ParentMembershipWorkerFailure):
            raise TypeError(
                "failure signal must carry ParentMembershipWorkerFailure"
            )
        if not self._parent_membership_event_matches_active(value):
            return
        model = self._parent_membership_model
        if model is None:
            return
        model.accept_failure(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

    @QtCore.Slot(object)
    def _accept_parent_membership_cancelled(self, value: object) -> None:
        if not isinstance(value, ParentMembershipCancelledReceipt):
            raise TypeError(
                "cancelled signal must carry ParentMembershipCancelledReceipt"
            )
        if not self._parent_membership_event_matches_active(value):
            return
        model = self._parent_membership_model
        if model is None:
            return
        model.accept_cancelled(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message)

    @QtCore.Slot()
    def _parent_membership_thread_finished(self) -> None:
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _refresh_parent_membership_editor(self) -> None:
        model = self._parent_membership_model
        if model is None:
            selected_user_parent = self._selected_parent_is_user_authored()
            self.editor.set_parent_membership_state(
                excluded=False,
                enabled=False,
                busy=False,
                status_text=(
                    "Membership for this selected user parent is controlled "
                    "through its Add Parent entry in History."
                    if selected_user_parent
                    else "Select a parent to manage membership"
                ),
                status_tone=PresentationTone.MUTED.value,
            )
            self._refresh_parent_geometry_editor()
            return
        state = model.state
        mutation_allowed = self._parent_membership_mutation_allowed()
        status_text = state.status_text
        status_tone = state.status_tone
        source_state = (
            self._source_text_model.state
            if self._source_text_model is not None
            else None
        )
        target_state = (
            self._target_text_model.state
            if self._target_text_model is not None
            else None
        )
        geometry_state = (
            self._parent_geometry_model.state
            if self._parent_geometry_model is not None
            else None
        )
        reading_order_state = (
            self._reading_order_model.state
            if self._reading_order_model is not None
            else None
        )
        history_state = (
            self._edit_history_model.state
            if self._edit_history_model is not None
            else None
        )
        if not state.busy and self._project_thread is not None:
            status_text = "Membership changes are paused while another project opens."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and not self._active_project_matches_projection():
            status_text = "Reload the active project before changing membership."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and history_state is not None
            and not history_state.stable_for_run
        ):
            status_text = (
                "Reload the active project before changing membership."
                if history_state.stale
                else "Wait for the edit-history action before changing membership."
            )
            status_tone = PresentationTone.WARNING.value
        elif not state.busy and source_state is not None and not source_state.stable_for_run:
            status_text = (
                "Reload the selected parent before changing membership."
                if source_state.stale
                else "Apply or Cancel the source-text draft before changing membership."
            )
            status_tone = PresentationTone.WARNING.value
        elif not state.busy and target_state is not None and not target_state.stable_for_run:
            status_text = (
                "Reload the selected parent before changing membership."
                if target_state.phase is TargetTextEditorPhase.STALE
                else "Apply or Cancel the target-text draft before changing membership."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and geometry_state is not None
            and not geometry_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before changing membership."
                if geometry_state.stale
                else "Apply or Cancel the geometry draft before changing membership."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and reading_order_state is not None
            and not reading_order_state.stable_for_run
        ):
            status_text = (
                "Reload the selected page before changing membership."
                if reading_order_state.stale
                else "Apply or Cancel the reading-order draft before changing membership."
            )
            status_tone = PresentationTone.WARNING.value
        self.editor.set_parent_membership_state(
            excluded=state.excluded,
            enabled=state.command_enabled and mutation_allowed,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
        )
        self._refresh_parent_geometry_editor()

    @QtCore.Slot(object)
    def _set_parent_geometry_draft(self, bbox: object) -> None:
        model = self._parent_geometry_model
        if model is None or not self._parent_geometry_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before changing geometry.",
                warning=True,
            )
            return
        try:
            model.set_draft_bbox(bbox)  # type: ignore[arg-type]
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _cancel_parent_geometry_draft(self) -> None:
        model = self._parent_geometry_model
        if model is None or model.state.busy:
            return
        try:
            model.cancel_draft()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _apply_parent_geometry_draft(self) -> None:
        model = self._parent_geometry_model
        if model is None or not self._parent_geometry_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before applying geometry.",
                warning=True,
            )
            return
        try:
            command = model.begin_apply()
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_parent_geometry_worker(command)

    def _start_parent_geometry_worker(
        self,
        command: ParentGeometryWorkerCommand,
    ) -> None:
        if self._parent_geometry_thread is not None:
            raise RuntimeError("a parent-geometry worker is already active")
        if not self._parent_geometry_mutation_allowed():
            raise RuntimeError("parent geometry is not currently editable")
        thread = QtCore.QThread(self)
        worker = ParentGeometryWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_parent_geometry_busy)
        worker.receipt.connect(self._accept_parent_geometry_receipt)
        worker.stale.connect(self._accept_parent_geometry_stale)
        worker.failure.connect(self._accept_parent_geometry_failure)
        worker.cancelled.connect(self._accept_parent_geometry_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_parent_geometry_thread",
            worker_attribute="_parent_geometry_worker",
            on_settled=self._parent_geometry_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_parent_geometry_busy(self, value: object) -> None:
        if not isinstance(value, ParentGeometryWorkerBusyState):
            raise TypeError(
                "busy signal must carry ParentGeometryWorkerBusyState"
            )
        model = self._parent_geometry_model
        if model is None or model.state.worker_command is None:
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()

    @QtCore.Slot(object)
    def _accept_parent_geometry_receipt(self, value: object) -> None:
        if not isinstance(value, ParentGeometryWorkerReceipt):
            raise TypeError(
                "receipt signal must carry ParentGeometryWorkerReceipt"
            )
        model = self._parent_geometry_model
        if model is None or not self._parent_geometry_receipt_matches_current(
            value,
            model,
        ):
            if model is not None:
                active_command = model.state.worker_command
                edit = value.command_receipt.edit
                if (
                    active_command is not None
                    and active_command.page_id == edit.page_id
                    and active_command.parent_id == edit.target.parent_id
                    and edit.domain.value == "structural"
                    and edit.operation == "set_geometry"
                    and active_command.bbox == value.command_receipt.after_bbox
                    and active_command.expected_effective_page_fingerprint
                    == value.command_receipt.before_effective_page_fingerprint
                ):
                    model.accept_stale(
                        ParentGeometryWorkerFailure(
                            code=ParentGeometryWorkerFailureCode.SNAPSHOT_STALE,
                            stage=ParentGeometryWorkerStage.COMPLETE,
                            project_path=active_command.project_path,
                            page_id=active_command.page_id,
                            parent_id=active_command.parent_id,
                            bbox=active_command.bbox,
                            message=(
                                "The geometry edit was saved, but the active project "
                                "changed. Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "A geometry edit finished for a project that is no longer active. "
                "Reopen that project to inspect the saved edit.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        selected_page = value.command_receipt.edit.page_id
        selected_parent = value.command_receipt.edit.target.parent_id
        self._project = dict(value.project)
        self._projection = value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "Parent geometry saved. The cleaned base and upstream results require "
            "explicit revalidation before this page can be previewed.",
            warning=True,
        )

    def _parent_geometry_receipt_matches_current(
        self,
        value: ParentGeometryWorkerReceipt,
        model: ParentGeometryEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        edit = value.command_receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        return bool(
            command is not None
            and command.page_id == edit.page_id
            and command.parent_id == edit.target.parent_id
            and edit.domain.value == "structural"
            and edit.operation == "set_geometry"
            and command.bbox == value.command_receipt.after_bbox
            and command.expected_effective_page_fingerprint
            == value.command_receipt.before_effective_page_fingerprint
            and value.command_receipt.canvas_size == state.selection.canvas_size
            and active_path
            == os.path.normcase(os.path.abspath(state.selection.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(os.path.abspath(application_project.project_path))
            == active_path
            and value.projection.metadata.project_id == edit.project_id
        )

    def _parent_geometry_event_matches_active(
        self,
        value: ParentGeometryWorkerFailure | ParentGeometryCancelledReceipt,
    ) -> bool:
        model = self._parent_geometry_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        return bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.bbox == value.bbox
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value.project_path))
        )

