    @QtCore.Slot()
    def _reading_order_thread_finished(self) -> None:
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _refresh_reading_order_editor(self) -> None:
        model = self._reading_order_model
        page = None
        parent_labels: dict[str, str] = {}
        if self._projection is not None and self._selected_page_id:
            try:
                page = self._projection.page(self._selected_page_id)
            except (KeyError, ValueError):
                page = None
            if page is not None:
                parent_labels = {
                    row.parent_id: row.display_text for row in page.parent_rows
                }
                automatic_order = tuple(page.automatic_ordered_parent_ids)
                for parent_id in self._merge_retained_automatic_parent_ids(page):
                    try:
                        ordinal = automatic_order.index(parent_id) + 1
                    except ValueError:
                        continue
                    parent_labels[parent_id] = (
                        f"Pipeline block {ordinal} · merged ancestry"
                    )
        if model is None:
            automatic_order: tuple[str, ...] = ()
            effective_order: tuple[str, ...] = ()
            excluded_parent_ids: tuple[str, ...] = ()
            if page is not None:
                automatic_order = page.automatic_ordered_parent_ids
                effective_order = tuple(
                    page.effective.hierarchy.ordered_parent_ids
                )
                excluded_parent_ids = tuple(
                    page.effective.hierarchy.excluded_parent_ids
                )
            status_text = (
                "Restore this excluded parent before changing its reading order."
                if self._selected_parent_id in set(excluded_parent_ids)
                else "Select an included parent to edit page reading order"
            )
            self.editor.set_reading_order_editor_state(
                automatic_order=automatic_order,
                effective_order=effective_order,
                proposed_order=effective_order,
                selected_parent_id=self._selected_parent_id,
                excluded_parent_ids=excluded_parent_ids,
                move_earlier_enabled=False,
                move_later_enabled=False,
                apply_enabled=False,
                cancel_enabled=False,
                busy=False,
                status_text=status_text,
                status_tone=PresentationTone.MUTED.value,
                parent_labels={
                    parent_id: parent_labels[parent_id]
                    for parent_id in automatic_order
                    if parent_id in parent_labels
                },
                merge_retained_automatic_parent_ids=(
                    self._merge_retained_automatic_parent_ids(page)
                    if page is not None
                    else ()
                ),
            )
            self._refresh_merge_parent_editor()
            return
        state = model.state
        mutation_allowed = self._reading_order_mutation_allowed()
        status_text = state.status_text
        status_tone = state.status_tone
        source_state = (
            self._source_text_model.state
            if self._source_text_model is not None
            else None
        )
        target_state = (
            self._target_text_model.state
            if self._target_text_model is not None
            else None
        )
        membership_state = (
            self._parent_membership_model.state
            if self._parent_membership_model is not None
            else None
        )
        geometry_state = (
            self._parent_geometry_model.state
            if self._parent_geometry_model is not None
            else None
        )
        writing_mode_state = (
            self._writing_mode_model.state
            if self._writing_mode_model is not None
            else None
        )
        history_state = (
            self._edit_history_model.state
            if self._edit_history_model is not None
            else None
        )
        if not state.busy and self._project_thread is not None:
            status_text = "Reading-order editing is paused while another project opens."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and self._application_model.state.pipeline_busy:
            status_text = "Reading-order editing is paused while a run is active."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and not self._active_project_matches_projection():
            status_text = "Reload the active project before editing reading order."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and history_state is not None
            and not history_state.stable_for_run
        ):
            status_text = (
                "Reload the active project before editing reading order."
                if history_state.stale
                else "Wait for the edit-history action before editing reading order."
            )
            status_tone = PresentationTone.WARNING.value
        elif not state.busy and source_state is not None and not source_state.stable_for_run:
            status_text = "Resolve the source-text draft before editing reading order."
            status_tone = PresentationTone.WARNING.value
        elif not state.busy and target_state is not None and not target_state.stable_for_run:
            status_text = "Resolve the target-text draft before editing reading order."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and membership_state is not None
            and not membership_state.stable_for_run
        ):
            status_text = "Reload after the membership action before editing reading order."
            status_tone = PresentationTone.WARNING.value
        elif not state.busy and geometry_state is not None and not geometry_state.stable_for_run:
            status_text = "Resolve the geometry draft before editing reading order."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and writing_mode_state is not None
            and not writing_mode_state.stable_for_run
        ):
            status_text = "Resolve the writing-mode draft before editing reading order."
            status_tone = PresentationTone.WARNING.value
        self.editor.set_reading_order_editor_state(
            automatic_order=state.selection.automatic_ordered_parent_ids,
            effective_order=state.selection.effective_ordered_parent_ids,
            proposed_order=state.draft_ordered_parent_ids,
            selected_parent_id=state.selection.selected_parent_id,
            excluded_parent_ids=state.selection.excluded_parent_ids,
            move_earlier_enabled=state.can_move_earlier and mutation_allowed,
            move_later_enabled=state.can_move_later and mutation_allowed,
            apply_enabled=state.apply_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
            merge_retained_automatic_parent_ids=(
                state.selection.merge_retained_automatic_parent_ids
            ),
            parent_labels={
                parent_id: parent_labels[parent_id]
                for parent_id in (
                    state.selection.effective_ordered_parent_ids
                    + state.selection.merge_retained_automatic_parent_ids
                )
                if parent_id in parent_labels
            },
        )
        self._refresh_merge_parent_editor()

    def _merge_parent_mutation_allowed(self) -> bool:
        model = self._merge_parent_model
        if model is None:
            return False
        state = model.state
        other_states = tuple(
            candidate.state
            for candidate in (
                self._source_text_model,
                self._target_text_model,
                self._parent_membership_model,
                self._parent_geometry_model,
                self._reading_order_model,
                self._split_parent_model,
                self._writing_mode_model,
                self._line_height_model,
                self._rotation_model,
                self._render_box_model,
                self._font_role_model,
                self._fill_color_model,
                self._outline_color_model,
                self._outline_width_model,
                self._preferred_size_model,
                self._shadow_color_model,
                self._shadow_blur_model,
                self._shadow_offset_model,
                self._edit_history_model,
            )
            if candidate is not None
        )
        return bool(
            state.editing_enabled
            and state.selection.page_id == self._selected_page_id
            and state.selection.source.parent_id == self._selected_parent_id
            and not self._application_model.state.pipeline_busy
            and not self._manual_cleanup_modal_active()
            and self._project_thread is None
            and self._source_text_thread is None
            and self._target_text_thread is None
            and self._parent_membership_thread is None
            and self._parent_geometry_thread is None
            and self._reading_order_thread is None
            and self._merge_parent_thread is None
            and self._split_parent_thread is None
            and self._writing_mode_thread is None
            and self._line_height_thread is None
            and self._rotation_thread is None
            and self._render_box_command_settled()
            and self._font_role_thread is None
            and self._font_weight_tier_command_settled()
            and self._fill_color_thread is None
            and self._outline_color_thread is None
            and self._outline_width_thread is None
            and self._preferred_size_thread is None
            and self._shadow_color_thread is None
            and self._shadow_blur_thread is None
            and self._shadow_offset_thread is None
            and self._shadow_visibility_thread is None
            and self._add_user_parent_thread is None
            and self._ocr_revision_thread is None
            and self._translation_revision_thread is None
            and self._edit_history_thread is None
            and all(candidate.stable_for_run for candidate in other_states)
            and self._add_user_parent_command_settled()
            and self._active_project_matches_projection()
        )

    @QtCore.Slot(object)
    def _set_merge_parent_partner(self, value: object) -> None:
        model = self._merge_parent_model
        if model is None or not self._merge_parent_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before changing Merge Parent.",
                warning=True,
            )
            return
        try:
            model.select_partner(value if isinstance(value, str) else None)
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _cancel_merge_parent_draft(self) -> None:
        model = self._merge_parent_model
        if model is None:
            return
        if self._merge_parent_thread is not None:
            worker = self._merge_parent_worker
            if worker is not None and model.state.cancellation_enabled:
                if worker.request_cancel():
                    self._set_notice("Cancelling Merge Parent before persistence…")
                return
            self._set_notice(
                "Merge Parent persistence has started and cannot be cancelled.",
                warning=True,
            )
            return
        try:
            model.cancel_draft()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _apply_merge_parent_draft(self) -> None:
        model = self._merge_parent_model
        if model is None or not self._merge_parent_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before merging these pipeline blocks.",
                warning=True,
            )
            return
        try:
            command = model.begin_merge()
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_merge_parent_worker(command)

    def _start_merge_parent_worker(
        self,
        command: MergePipelineParentsWorkerCommand,
    ) -> None:
        if not isinstance(command, MergePipelineParentsWorkerCommand):
            raise TypeError("command must be MergePipelineParentsWorkerCommand")
        if self._merge_parent_thread is not None:
            raise RuntimeError("a Merge Parent worker is already active")
        model = self._merge_parent_model
        if model is None or model.state.worker_command != command:
            raise RuntimeError("Merge Parent command is not the active fixed draft")
        thread = QtCore.QThread(self)
        worker = MergePipelineParentsWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_merge_parent_busy)
        worker.receipt.connect(self._accept_merge_parent_receipt)
        worker.stale.connect(self._accept_merge_parent_stale)
        worker.failure.connect(self._accept_merge_parent_failure)
        worker.cancelled.connect(self._accept_merge_parent_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_merge_parent_thread",
            worker_attribute="_merge_parent_worker",
            on_settled=self._merge_parent_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_merge_parent_busy(self, value: object) -> None:
        if not isinstance(value, MergePipelineParentsWorkerBusyState):
            raise TypeError("busy signal must carry MergePipelineParentsWorkerBusyState")
        model = self._merge_parent_model
        if model is None or not self._merge_parent_event_matches_active(value):
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _merge_parent_receipt_matches_command(
        self,
        value: MergePipelineParentsWorkerReceipt,
        model: MergePipelineParentsEditorModel,
    ) -> bool:
        command = model.state.worker_command
        if command is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        commit = receipt.commit_receipt
        return bool(
            receipt.source_parent_ids == command.source_parent_ids
            and receipt.merged_parent_id == command.merged_parent_id
            and receipt.merged_root_id == command.merged_root_id
            and receipt.before_effective_page_fingerprint
            == command.expected_effective_page_fingerprint
            and receipt.before_hierarchy_revision_id
            == command.expected_hierarchy_revision_id
            and receipt.before_hierarchy_fingerprint
            == command.expected_hierarchy_fingerprint
            and receipt.command_id == edit.edit_id == commit.transaction_id
            and edit.domain is EditDomain.STRUCTURAL
            and edit.operation == MergePipelineParentsOperation.MERGE.value
            and edit.target.kind is EditTargetKind.PARENT
            and edit.target.parent_id == command.merged_parent_id
            and commit.page_id == command.page_id == edit.page_id
            and commit.edit_ids == (edit.edit_id,)
            and commit.artifact_revision_ids == ()
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(model.state.selection.project_path))
        )

    def _merge_parent_receipt_matches_current(
        self,
        value: MergePipelineParentsWorkerReceipt,
        model: MergePipelineParentsEditorModel,
    ) -> bool:
        if not self._merge_parent_receipt_matches_command(value, model):
            return False
        command = model.state.worker_command
        if command is None or self._projection is None:
            return False
        try:
            current_page = self._projection.page(command.page_id)
            for parent_id in command.source_parent_ids:
                current_page.parent(parent_id)
        except (KeyError, ValueError):
            return False
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        edit = value.command_receipt.edit
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        return bool(
            self._selected_page_id == command.page_id
            and self._selected_parent_id == model.state.selection.source.parent_id
            and current_page.effective.effective_fingerprint
            == command.expected_effective_page_fingerprint
            and current_page.hierarchy_revision.revision_id
            == command.expected_hierarchy_revision_id
            and current_page.hierarchy_revision.fingerprint
            == command.expected_hierarchy_fingerprint
            and active_path
            == os.path.normcase(os.path.abspath(command.project_path))
            and active_path
            == os.path.normcase(os.path.abspath(value.projection.metadata.project_path))
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and value.projection.metadata.project_id == edit.project_id
        )

    @QtCore.Slot(object)
    def _accept_merge_parent_receipt(self, value: object) -> None:
        if not isinstance(value, MergePipelineParentsWorkerReceipt):
            raise TypeError("receipt signal must carry MergePipelineParentsWorkerReceipt")
        model = self._merge_parent_model
        if model is None or not self._merge_parent_receipt_matches_current(value, model):
            if model is not None and self._merge_parent_receipt_matches_command(value, model):
                command = model.state.worker_command
                if command is not None:
                    model.accept_stale(
                        MergePipelineParentsWorkerFailure(
                            code=MergePipelineParentsWorkerFailureCode.SNAPSHOT_STALE,
                            stage=MergePipelineParentsWorkerStage.COMPLETE,
                            project_path=command.project_path,
                            page_id=command.page_id,
                            source_parent_ids=command.source_parent_ids,
                            message=(
                                "Merge Parent was saved, but the active project changed. "
                                "Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
            self._set_notice(
                "Merge Parent finished for a project that is no longer active. "
                "Reopen it to inspect the saved merged parent.",
                warning=True,
            )
            self._refresh_target_text_editor()
            self._refresh_run_presentation()
            return
        model.accept_receipt(value)
        receipt = value.command_receipt
        self._project, self._projection = dict(value.project), value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = receipt.edit.page_id
        self._selected_parent_id = receipt.merged_parent_id
        self.select_page(receipt.edit.page_id)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "Pipeline parents merged. Their exact ordered OCR is current; "
            "translation and every later owner remain explicit.",
            warning=True,
        )

    def _merge_parent_event_matches_active(self, value: Any) -> bool:
        model = self._merge_parent_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        value_path = getattr(value, "project_path", command.project_path)
        return bool(
            command.page_id == value.page_id
            and command.source_parent_ids == tuple(value.source_parent_ids)
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value_path))
        )

