    @QtCore.Slot()
    def _merge_parent_thread_finished(self) -> None:
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _refresh_merge_parent_editor(self) -> None:
        model = self._merge_parent_model
        if model is None:
            self.editor.set_merge_parent_editor_state(
                candidates=(),
                selected_partner_id="",
                source_parent_ids=None,
                source_bboxes=None,
                merged_bbox=None,
                merged_source_text="",
                editing_enabled=False,
                merge_enabled=False,
                cancel_enabled=False,
                busy=False,
                status_text=self._merge_parent_unavailable_reason,
                status_tone=PresentationTone.MUTED.value,
            )
            self._refresh_split_parent_editor()
            return
        state = model.state
        mutation_allowed = self._merge_parent_mutation_allowed()
        candidates = tuple(
            (candidate.parent_id, candidate.label)
            for candidate in state.selection.candidates
        )
        source_parent_ids = None
        source_bboxes = None
        merged_bbox = None
        merged_source_text = ""
        if state.partner_parent_id:
            partner = next(
                candidate
                for candidate in state.selection.candidates
                if candidate.parent_id == state.partner_parent_id
            )
            ordered = tuple(
                sorted(
                    (state.selection.source, partner),
                    key=lambda candidate: candidate.order_index,
                )
            )
            source_parent_ids = (ordered[0].parent_id, ordered[1].parent_id)
            source_bboxes = (ordered[0].bbox, ordered[1].bbox)
            merged_bbox = merged_pipeline_parent_bbox(source_bboxes)
            merged_source_text = ordered[0].source_text + ordered[1].source_text
        status_text = state.message
        status_tone = _MERGE_PIPELINE_PARENT_TONES[state.phase]
        if not state.busy and not mutation_allowed and state.selection.available:
            status_text = (
                "Finish the active editor command before changing Merge Parent."
            )
            status_tone = PresentationTone.MUTED.value
        self.editor.set_merge_parent_editor_state(
            candidates=candidates,
            selected_partner_id=state.partner_parent_id,
            source_parent_ids=source_parent_ids,
            source_bboxes=source_bboxes,
            merged_bbox=merged_bbox,
            merged_source_text=merged_source_text,
            editing_enabled=state.editing_enabled and mutation_allowed,
            merge_enabled=state.merge_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
        )
        self._refresh_split_parent_editor()

    def _split_parent_mutation_allowed(self) -> bool:
        model = self._split_parent_model
        if model is None:
            return False
        state = model.state
        other_states = tuple(
            candidate.state
            for candidate in (
                self._source_text_model,
                self._target_text_model,
                self._parent_membership_model,
                self._parent_geometry_model,
                self._reading_order_model,
                self._merge_parent_model,
                self._writing_mode_model,
                self._line_height_model,
                self._rotation_model,
                self._render_box_model,
                self._font_role_model,
                self._fill_color_model,
                self._outline_color_model,
                self._outline_width_model,
                self._preferred_size_model,
                self._shadow_color_model,
                self._shadow_blur_model,
                self._shadow_offset_model,
                self._edit_history_model,
            )
            if candidate is not None
        )
        return bool(
            state.editing_enabled
            and state.selection.page_id == self._selected_page_id
            and state.selection.source_parent_id == self._selected_parent_id
            and not self._application_model.state.pipeline_busy
            and not self._manual_cleanup_modal_active()
            and self._project_thread is None
            and self._source_text_thread is None
            and self._target_text_thread is None
            and self._parent_membership_thread is None
            and self._parent_geometry_thread is None
            and self._reading_order_thread is None
            and self._merge_parent_thread is None
            and self._split_parent_thread is None
            and self._writing_mode_thread is None
            and self._line_height_thread is None
            and self._rotation_thread is None
            and self._render_box_command_settled()
            and self._font_role_thread is None
            and self._font_weight_tier_command_settled()
            and self._fill_color_thread is None
            and self._outline_color_thread is None
            and self._outline_width_thread is None
            and self._preferred_size_thread is None
            and self._shadow_color_thread is None
            and self._shadow_blur_thread is None
            and self._shadow_offset_thread is None
            and self._shadow_visibility_thread is None
            and self._add_user_parent_thread is None
            and self._ocr_revision_thread is None
            and self._translation_revision_thread is None
            and self._edit_history_thread is None
            and all(candidate.stable_for_run for candidate in other_states)
            and self._add_user_parent_command_settled()
            and self._active_project_matches_projection()
        )

