    @QtCore.Slot()
    def _split_parent_thread_finished(self) -> None:
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _refresh_split_parent_editor(self) -> None:
        model = self._split_parent_model
        if model is None:
            self.editor.set_split_parent_editor_state(
                source_bbox=None,
                child_bboxes=None,
                orientation=None,
                split_offset=None,
                editing_enabled=False,
                split_enabled=False,
                cancel_enabled=False,
                busy=False,
                status_text=self._split_parent_unavailable_reason,
                status_tone=PresentationTone.MUTED.value,
            )
            self._refresh_writing_mode_editor()
            return
        state = model.state
        mutation_allowed = self._split_parent_mutation_allowed()
        orientation = (
            state.draft_orientation.value
            if state.draft_orientation is not None
            else None
        )
        child_bboxes = None
        if state.valid and state.draft_orientation is not None:
            assert state.draft_split_offset is not None
            child_bboxes = split_user_parent_bboxes(
                state.selection.source_workflow_area_bbox,
                orientation=state.draft_orientation,
                split_offset=state.draft_split_offset,
            )
        status_text = state.status_text
        status_tone = _SPLIT_USER_PARENT_TONES[state.phase]
        if not state.busy and not mutation_allowed and state.selection.available:
            status_text = (
                "Finish the active editor command before changing Split Parent."
            )
            status_tone = PresentationTone.MUTED.value
        self.editor.set_split_parent_editor_state(
            source_bbox=state.selection.source_workflow_area_bbox,
            child_bboxes=child_bboxes,
            orientation=orientation,
            split_offset=state.draft_split_offset,
            editing_enabled=state.editing_enabled and mutation_allowed,
            split_enabled=state.split_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
        )
        self._refresh_writing_mode_editor()

    @QtCore.Slot(str)
    def _set_writing_mode_draft(self, writing_mode: str) -> None:
        model = self._writing_mode_model
        if model is None or not self._writing_mode_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before changing writing mode.",
                warning=True,
            )
            return
        try:
            model.set_draft_writing_mode(writing_mode)
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _cancel_writing_mode_draft(self) -> None:
        model = self._writing_mode_model
        if model is None or model.state.busy:
            return
        try:
            model.cancel_draft()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _apply_writing_mode_draft(self) -> None:
        model = self._writing_mode_model
        if model is None or not self._writing_mode_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before setting writing mode.",
                warning=True,
            )
            return
        try:
            command = model.begin_set()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_writing_mode_worker(command)

    @QtCore.Slot()
    def _restore_automatic_writing_mode(self) -> None:
        model = self._writing_mode_model
        if model is None or not self._writing_mode_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before restoring writing mode.",
                warning=True,
            )
            return
        try:
            command = model.begin_restore()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_writing_mode_worker(command)

    def _start_writing_mode_worker(
        self,
        command: RenderLayoutWritingModeWorkerCommand,
    ) -> None:
        if not isinstance(command, RenderLayoutWritingModeWorkerCommand):
            raise TypeError(
                "command must be RenderLayoutWritingModeWorkerCommand"
            )
        if self._writing_mode_thread is not None:
            raise RuntimeError("a writing-mode worker is already active")
        if not self._writing_mode_mutation_allowed():
            raise RuntimeError("writing mode is not currently editable")
        thread = QtCore.QThread(self)
        worker = RenderLayoutWritingModeWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_writing_mode_busy)
        worker.receipt.connect(self._accept_writing_mode_receipt)
        worker.stale.connect(self._accept_writing_mode_stale)
        worker.failure.connect(self._accept_writing_mode_failure)
        worker.cancelled.connect(self._accept_writing_mode_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_writing_mode_thread",
            worker_attribute="_writing_mode_worker",
            on_settled=self._writing_mode_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_writing_mode_busy(self, value: object) -> None:
        if not isinstance(value, RenderLayoutWritingModeWorkerBusyState):
            raise TypeError(
                "busy signal must carry RenderLayoutWritingModeWorkerBusyState"
            )
        model = self._writing_mode_model
        command = model.state.worker_command if model is not None else None
        if (
            model is None
            or command is None
            or command.page_id != value.page_id
            or command.parent_id != value.parent_id
        ):
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @staticmethod
    def _writing_mode_edit_matches_command(
        edit: Any,
        command: RenderLayoutWritingModeWorkerCommand,
    ) -> bool:
        payload = dict(edit.payload)
        fields = payload.get("fields")
        if command.operation.value == "set":
            payload_matches = bool(
                set(payload) == {"fields"}
                and isinstance(fields, Mapping)
                and dict(fields) == {"writing_mode": command.writing_mode}
            )
            edit_operation = "set_fields"
        else:
            payload_matches = bool(
                set(payload) == {"fields"}
                and isinstance(fields, tuple)
                and fields == ("writing_mode",)
            )
            edit_operation = "restore_automatic"
        return bool(
            edit.domain is EditDomain.RENDER_LAYOUT
            and edit.operation == edit_operation
            and edit.page_id == command.page_id
            and edit.target.kind.value == "parent"
            and edit.target.parent_id == command.parent_id
            and payload_matches
        )

    def _writing_mode_receipt_matches_command(
        self,
        value: RenderLayoutWritingModeWorkerReceipt,
        model: RenderLayoutWritingModeEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        receipt = value.command_receipt
        if command is None:
            return False
        if command.operation.value == "set":
            after_matches = bool(
                receipt.after_writing_mode == command.writing_mode
                and receipt.after_writing_mode_authority == "user"
            )
        else:
            after_matches = bool(
                command.writing_mode == ""
                and receipt.after_writing_mode
                == receipt.automatic_writing_mode
                and receipt.after_writing_mode_authority == "automatic"
            )
        return bool(
            self._writing_mode_edit_matches_command(receipt.edit, command)
            and command.expected_effective_page_fingerprint
            == receipt.before_effective_page_fingerprint
            and receipt.automatic_writing_mode
            == state.selection.automatic_writing_mode
            and receipt.before_writing_mode
            == state.selection.effective_writing_mode
            and receipt.before_writing_mode_authority
            == state.selection.writing_mode_authority
            and after_matches
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(
                os.path.abspath(state.selection.project_path)
            )
        )

    def _writing_mode_receipt_matches_current(
        self,
        value: RenderLayoutWritingModeWorkerReceipt,
        model: RenderLayoutWritingModeEditorModel,
    ) -> bool:
        if not self._writing_mode_receipt_matches_command(value, model):
            return False
        state = model.state
        command = state.worker_command
        if command is None or self._projection is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        project_record = value.project.get("project")
        returned_project_id = (
            str(project_record.get("project_id") or "")
            if isinstance(project_record, Mapping)
            else ""
        )
        try:
            current_parent = self._projection.page(command.page_id).parent(
                command.parent_id
            )
        except (KeyError, ValueError):
            return False
        return bool(
            current_parent.automatic_writing_mode
            == receipt.automatic_writing_mode
            and current_parent.effective_writing_mode
            == receipt.before_writing_mode
            and current_parent.writing_mode_authority
            == receipt.before_writing_mode_authority
            and active_path
            == os.path.normcase(os.path.abspath(command.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(
                os.path.abspath(application_project.project_path)
            )
            == active_path
            and value.projection.metadata.project_id == edit.project_id
            and returned_project_id == edit.project_id
        )

    @QtCore.Slot(object)
    def _accept_writing_mode_receipt(self, value: object) -> None:
        if not isinstance(value, RenderLayoutWritingModeWorkerReceipt):
            raise TypeError(
                "receipt signal must carry RenderLayoutWritingModeWorkerReceipt"
            )
        model = self._writing_mode_model
        if model is None or not self._writing_mode_receipt_matches_current(
            value,
            model,
        ):
            if (
                model is not None
                and self._writing_mode_receipt_matches_command(value, model)
            ):
                active_command = model.state.worker_command
                if active_command is not None:
                    model.accept_stale(
                        RenderLayoutWritingModeWorkerFailure(
                            code=(
                                RenderLayoutWritingModeWorkerFailureCode.SNAPSHOT_STALE
                            ),
                            stage=RenderLayoutWritingModeWorkerStage.COMPLETE,
                            project_path=active_command.project_path,
                            page_id=active_command.page_id,
                            parent_id=active_command.parent_id,
                            operation=active_command.operation,
                            writing_mode=active_command.writing_mode,
                            message=(
                                "The writing-mode edit was saved, but the active "
                                "project changed. Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "A writing-mode edit finished for a project that is no longer "
                "active. Reopen that project to inspect the saved edit.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        receipt = value.command_receipt
        selected_page = receipt.edit.page_id
        selected_parent = receipt.edit.target.parent_id
        self._project, self._projection = dict(value.project), value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "Writing mode saved. Preview this page explicitly to render the change."
        )

    def _writing_mode_event_matches_active(
        self,
        value: (
            RenderLayoutWritingModeWorkerFailure
            | RenderLayoutWritingModeCancelledReceipt
        ),
    ) -> bool:
        model = self._writing_mode_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        return bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.operation is value.operation
            and command.writing_mode == value.writing_mode
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value.project_path))
        )

    @QtCore.Slot(object)
    def _accept_writing_mode_stale(self, value: object) -> None:
        if not isinstance(value, RenderLayoutWritingModeWorkerFailure):
            raise TypeError(
                "stale signal must carry RenderLayoutWritingModeWorkerFailure"
            )
        if not self._writing_mode_event_matches_active(value):
            return
        model = self._writing_mode_model
        if model is None:
            return
        model.accept_stale(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

    @QtCore.Slot(object)
    def _accept_writing_mode_failure(self, value: object) -> None:
        if not isinstance(value, RenderLayoutWritingModeWorkerFailure):
            raise TypeError(
                "failure signal must carry RenderLayoutWritingModeWorkerFailure"
            )
        if not self._writing_mode_event_matches_active(value):
            return
        model = self._writing_mode_model
        if model is None:
            return
        model.accept_failure(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

    @QtCore.Slot(object)
    def _accept_writing_mode_cancelled(self, value: object) -> None:
        if not isinstance(value, RenderLayoutWritingModeCancelledReceipt):
            raise TypeError(
                "cancelled signal must carry RenderLayoutWritingModeCancelledReceipt"
            )
        if not self._writing_mode_event_matches_active(value):
            return
        model = self._writing_mode_model
