    def _start_line_height_worker(
        self,
        command: RenderLayoutLineHeightWorkerCommand,
    ) -> None:
        if not isinstance(command, RenderLayoutLineHeightWorkerCommand):
            raise TypeError(
                "command must be RenderLayoutLineHeightWorkerCommand"
            )
        if self._line_height_thread is not None:
            raise RuntimeError("a line-height worker is already active")
        if not self._line_height_mutation_allowed():
            raise RuntimeError("line height is not currently editable")
        thread = QtCore.QThread(self)
        worker = RenderLayoutLineHeightWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_line_height_busy)
        worker.receipt.connect(self._accept_line_height_receipt)
        worker.stale.connect(self._accept_line_height_stale)
        worker.failure.connect(self._accept_line_height_failure)
        worker.cancelled.connect(self._accept_line_height_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_line_height_thread",
            worker_attribute="_line_height_worker",
            on_settled=self._line_height_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_line_height_busy(self, value: object) -> None:
        if not isinstance(value, RenderLayoutLineHeightWorkerBusyState):
            raise TypeError(
                "busy signal must carry RenderLayoutLineHeightWorkerBusyState"
            )
        model = self._line_height_model
        command = model.state.worker_command if model is not None else None
        if (
            model is None
            or command is None
            or command.page_id != value.page_id
            or command.parent_id != value.parent_id
        ):
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @staticmethod
    def _line_height_edit_matches_command(
        edit: Any,
        command: RenderLayoutLineHeightWorkerCommand,
    ) -> bool:
        payload = dict(edit.payload)
        fields = payload.get("fields")
        if command.operation.value == "set":
            payload_matches = bool(
                command.line_height is not None
                and set(payload) == {"fields"}
                and isinstance(fields, Mapping)
                and dict(fields) == {"line_height": command.line_height}
            )
            edit_operation = "set_fields"
        else:
            payload_matches = bool(
                command.line_height is None
                and set(payload) == {"fields"}
                and isinstance(fields, tuple)
                and fields == ("line_height",)
            )
            edit_operation = "restore_automatic"
        return bool(
            edit.domain is EditDomain.RENDER_LAYOUT
            and edit.operation == edit_operation
            and edit.page_id == command.page_id
            and edit.target.kind is EditTargetKind.PARENT
            and edit.target.parent_id == command.parent_id
            and not edit.target.artifact_id
            and not edit.target.edit_id
            and payload_matches
        )

    def _line_height_receipt_matches_command(
        self,
        value: RenderLayoutLineHeightWorkerReceipt,
        model: RenderLayoutLineHeightEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        receipt = value.command_receipt
        if command is None:
            return False
        if command.operation.value == "set":
            after_matches = bool(
                command.line_height is not None
                and receipt.after_line_height == command.line_height
                and receipt.after_line_height_authority == "user"
            )
        else:
            after_matches = bool(
                command.line_height is None
                and receipt.after_line_height
                == receipt.automatic_line_height
                and receipt.after_line_height_authority == "automatic"
            )
        edit = receipt.edit
        commit = receipt.commit_receipt
        return bool(
            self._line_height_edit_matches_command(edit, command)
            and receipt.command_id == edit.edit_id == commit.transaction_id
            and receipt.superseded_edit_id == edit.supersedes_edit_id
            and commit.page_id == command.page_id == edit.page_id
            and commit.edit_ids == (edit.edit_id,)
            and commit.artifact_revision_ids == ()
            and command.expected_effective_page_fingerprint
            == receipt.before_effective_page_fingerprint
            and receipt.automatic_line_height
            == state.selection.automatic_line_height
            and receipt.before_line_height
            == state.selection.effective_line_height
            and receipt.before_line_height_authority
            == state.selection.line_height_authority
            and after_matches
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(
                os.path.abspath(state.selection.project_path)
            )
        )

    def _line_height_receipt_matches_current(
        self,
        value: RenderLayoutLineHeightWorkerReceipt,
        model: RenderLayoutLineHeightEditorModel,
    ) -> bool:
        if not self._line_height_receipt_matches_command(value, model):
            return False
        state = model.state
        command = state.worker_command
        if command is None or self._projection is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        project_record = value.project.get("project")
        returned_project_id = (
            str(project_record.get("project_id") or "")
            if isinstance(project_record, Mapping)
            else ""
        )
        try:
            current_parent = self._projection.page(command.page_id).parent(
                command.parent_id
            )
        except (KeyError, ValueError):
            return False
        return bool(
            current_parent.automatic_line_height
            == receipt.automatic_line_height
            and current_parent.effective_line_height
            == receipt.before_line_height
            and current_parent.line_height_authority
            == receipt.before_line_height_authority
            and self._selected_page_id == command.page_id
            and self._selected_parent_id == command.parent_id
            and active_path
            == os.path.normcase(os.path.abspath(command.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(
                os.path.abspath(application_project.project_path)
            )
            == active_path
            and value.projection.metadata.project_id == edit.project_id
            and returned_project_id == edit.project_id
        )

    @QtCore.Slot(object)
    def _accept_line_height_receipt(self, value: object) -> None:
        if not isinstance(value, RenderLayoutLineHeightWorkerReceipt):
            raise TypeError(
                "receipt signal must carry RenderLayoutLineHeightWorkerReceipt"
            )
        model = self._line_height_model
        if model is None or not self._line_height_receipt_matches_current(
            value,
            model,
        ):
            if (
                model is not None
                and self._line_height_receipt_matches_command(value, model)
            ):
                active_command = model.state.worker_command
                if active_command is not None:
                    model.accept_stale(
                        RenderLayoutLineHeightWorkerFailure(
                            code=(
                                RenderLayoutLineHeightWorkerFailureCode.SNAPSHOT_STALE
                            ),
                            stage=RenderLayoutLineHeightWorkerStage.COMPLETE,
                            project_path=active_command.project_path,
                            page_id=active_command.page_id,
                            parent_id=active_command.parent_id,
                            operation=active_command.operation,
                            line_height=active_command.line_height,
                            message=(
                                "The line-height edit was saved, but the active "
                                "project changed. Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "A line-height edit finished for a project that is no longer "
                "active. Reopen that project to inspect the saved edit.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        receipt = value.command_receipt
        selected_page = receipt.edit.page_id
        selected_parent = receipt.edit.target.parent_id
        self._project, self._projection = dict(value.project), value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "Line height saved. Preview this page explicitly to render the change."
        )

    def _line_height_event_matches_active(
        self,
        value: (
            RenderLayoutLineHeightWorkerFailure
            | RenderLayoutLineHeightCancelledReceipt
        ),
    ) -> bool:
        model = self._line_height_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        return bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.operation is value.operation
            and command.line_height == value.line_height
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value.project_path))
        )

    @QtCore.Slot(object)
    def _accept_line_height_stale(self, value: object) -> None:
        if not isinstance(value, RenderLayoutLineHeightWorkerFailure):
            raise TypeError(
                "stale signal must carry RenderLayoutLineHeightWorkerFailure"
            )
        if not self._line_height_event_matches_active(value):
            return
        model = self._line_height_model
        if model is None:
            return
        model.accept_stale(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

