    @QtCore.Slot()
    def _line_height_thread_finished(self) -> None:
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _refresh_line_height_editor(self) -> None:
        model = self._line_height_model
        if model is None:
            if not self._selected_parent_id:
                self.editor.set_line_height_editor_state(
                    automatic_line_height=None,
                    user_line_height=None,
                    effective_line_height=None,
                    draft_line_height=None,
                    line_height_authority="automatic",
                    render_required=False,
                    editing_enabled=False,
                    apply_enabled=False,
                    cancel_enabled=False,
                    restore_enabled=False,
                    busy=False,
                    status_text=(
                        "Select a render-required parent to edit line height"
                    ),
                    status_tone=PresentationTone.MUTED.value,
                )
            self._refresh_rotation_editor()
            return
        state = model.state
        mutation_allowed = self._line_height_mutation_allowed()
        status_text = state.status_text
        status_tone = _LINE_HEIGHT_TONES[state.phase]
        source_state = (
            self._source_text_model.state
            if self._source_text_model is not None
            else None
        )
        target_state = (
            self._target_text_model.state
            if self._target_text_model is not None
            else None
        )
        membership_state = (
            self._parent_membership_model.state
            if self._parent_membership_model is not None
            else None
        )
        geometry_state = (
            self._parent_geometry_model.state
            if self._parent_geometry_model is not None
            else None
        )
        reading_order_state = (
            self._reading_order_model.state
            if self._reading_order_model is not None
            else None
        )
        writing_mode_state = (
            self._writing_mode_model.state
            if self._writing_mode_model is not None
            else None
        )
        history_state = (
            self._edit_history_model.state
            if self._edit_history_model is not None
            else None
        )
        if not state.busy and self._project_thread is not None:
            status_text = "Line-height editing is paused while another project opens."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and self._application_model.state.pipeline_busy:
            status_text = "Line-height editing is paused while a run is active."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and not self._active_project_matches_projection():
            status_text = "Reload the active project before editing line height."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and history_state is not None
            and not history_state.stable_for_run
        ):
            status_text = (
                "Reload the active project before editing line height."
                if history_state.stale
                else "Wait for the edit-history action before editing line height."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and source_state is not None
            and not source_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing line height."
                if source_state.stale
                else "Apply or Cancel the source-text draft before editing line height."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and target_state is not None
            and not target_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing line height."
                if target_state.phase is TargetTextEditorPhase.STALE
                else "Apply or Cancel the target-text draft before editing line height."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and membership_state is not None
            and not membership_state.stable_for_run
        ):
            status_text = "Reload the selected parent before editing line height."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and geometry_state is not None
            and not geometry_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing line height."
                if geometry_state.stale
                else "Apply or Cancel the geometry draft before editing line height."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and reading_order_state is not None
            and not reading_order_state.stable_for_run
        ):
            status_text = (
                "Reload the selected page before editing line height."
                if reading_order_state.stale
                else "Apply or Cancel the reading-order draft before editing line height."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and writing_mode_state is not None
            and not writing_mode_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing line height."
                if writing_mode_state.stale
                else "Set or Cancel the writing-mode draft before editing line height."
            )
            status_tone = PresentationTone.WARNING.value
        self.editor.set_line_height_editor_state(
            automatic_line_height=state.selection.automatic_line_height,
            user_line_height=state.selection.user_line_height,
            effective_line_height=state.selection.effective_line_height,
            draft_line_height=state.draft_line_height,
            line_height_authority=state.selection.line_height_authority,
            render_required=state.selection.render_required,
            editing_enabled=state.editing_enabled and mutation_allowed,
            apply_enabled=state.apply_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            restore_enabled=state.restore_enabled and mutation_allowed,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
        )
        self._refresh_rotation_editor()

