    def _refresh_preferred_size_editor(self) -> None:
        model = self._preferred_size_model
        if model is None:
            if not self._selected_parent_id:
                self.editor.set_preferred_size_editor_state(
                    automatic_preferred_size=None,
                    user_preferred_size=None,
                    effective_preferred_size=None,
                    draft_preferred_size=None,
                    preferred_size_authority="automatic",
                    render_required=False,
                    editing_enabled=False,
                    apply_enabled=False,
                    cancel_enabled=False,
                    restore_enabled=False,
                    busy=False,
                    status_text=(
                        "Select a render-required parent to edit preferred size"
                    ),
                    status_tone=PresentationTone.MUTED.value,
                )
            self._refresh_add_user_parent_editor()
            return
        state = model.state
        mutation_allowed = self._preferred_size_mutation_allowed()
        status_text = state.status_text
        status_tone = _PREFERRED_SIZE_TONES[state.phase]
        source_state = (
            self._source_text_model.state
            if self._source_text_model is not None
            else None
        )
        target_state = (
            self._target_text_model.state
            if self._target_text_model is not None
            else None
        )
        membership_state = (
            self._parent_membership_model.state
            if self._parent_membership_model is not None
            else None
        )
        geometry_state = (
            self._parent_geometry_model.state
            if self._parent_geometry_model is not None
            else None
        )
        reading_order_state = (
            self._reading_order_model.state
            if self._reading_order_model is not None
            else None
        )
        writing_mode_state = (
            self._writing_mode_model.state
            if self._writing_mode_model is not None
            else None
        )
        history_state = (
            self._edit_history_model.state
            if self._edit_history_model is not None
            else None
        )
        if not state.busy and self._project_thread is not None:
            status_text = "Preferred-size editing is paused while another project opens."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and self._application_model.state.pipeline_busy:
            status_text = "Preferred-size editing is paused while a run is active."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and not self._active_project_matches_projection():
            status_text = "Reload the active project before editing preferred size."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and history_state is not None
            and not history_state.stable_for_run
        ):
            status_text = (
                "Reload the active project before editing preferred size."
                if history_state.stale
                else "Wait for the edit-history action before editing preferred size."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and source_state is not None
            and not source_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing preferred size."
                if source_state.stale
                else "Apply or Cancel the source-text draft before editing preferred size."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and target_state is not None
            and not target_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing preferred size."
                if target_state.phase is TargetTextEditorPhase.STALE
                else "Apply or Cancel the target-text draft before editing preferred size."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and membership_state is not None
            and not membership_state.stable_for_run
        ):
            status_text = "Reload the selected parent before editing preferred size."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and geometry_state is not None
            and not geometry_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing preferred size."
                if geometry_state.stale
                else "Apply or Cancel the geometry draft before editing preferred size."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and reading_order_state is not None
            and not reading_order_state.stable_for_run
        ):
            status_text = (
                "Reload the selected page before editing preferred size."
                if reading_order_state.stale
                else "Apply or Cancel the reading-order draft before editing preferred size."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and writing_mode_state is not None
            and not writing_mode_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing preferred size."
                if writing_mode_state.stale
                else "Set or Cancel the writing-mode draft before editing preferred size."
            )
            status_tone = PresentationTone.WARNING.value
        elif not state.busy and not mutation_allowed:
            status_text = (
                "Resolve the active editor command before editing preferred size."
            )
            status_tone = PresentationTone.WARNING.value
        self.editor.set_preferred_size_editor_state(
            automatic_preferred_size=state.selection.automatic_preferred_size,
            user_preferred_size=state.selection.user_preferred_size,
            effective_preferred_size=state.selection.effective_preferred_size,
            draft_preferred_size=state.draft_preferred_size,
            preferred_size_authority=state.selection.preferred_size_authority,
            render_required=state.selection.render_required,
            editing_enabled=state.editing_enabled and mutation_allowed,
            apply_enabled=state.apply_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            restore_enabled=state.restore_enabled and mutation_allowed,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
        )
        self._refresh_add_user_parent_editor()

    @QtCore.Slot(bool)
    def _set_shadow_blur_draft(self, shadow_blur: float) -> None:
        model = self._shadow_blur_model
        if model is None or not self._shadow_blur_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before changing shadow blur.",
                warning=True,
            )
            return
        try:
            model.set_draft_shadow_blur(shadow_blur)
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _cancel_shadow_blur_draft(self) -> None:
        model = self._shadow_blur_model
        if model is None or model.state.busy:
            return
        try:
            model.cancel_draft()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
