    def _start_shadow_offset_worker(
        self,
        command: RenderStyleShadowOffsetWorkerCommand,
    ) -> None:
        if not isinstance(command, RenderStyleShadowOffsetWorkerCommand):
            raise TypeError(
                "command must be RenderStyleShadowOffsetWorkerCommand"
            )
        if self._shadow_offset_thread is not None:
            raise RuntimeError("a shadow-offset worker is already active")
        if not self._shadow_offset_mutation_allowed():
            raise RuntimeError("shadow offset is not currently editable")
        thread = QtCore.QThread(self)
        worker = RenderStyleShadowOffsetWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_shadow_offset_busy)
        worker.receipt.connect(self._accept_shadow_offset_receipt)
        worker.stale.connect(self._accept_shadow_offset_stale)
        worker.failure.connect(self._accept_shadow_offset_failure)
        worker.cancelled.connect(self._accept_shadow_offset_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_shadow_offset_thread",
            worker_attribute="_shadow_offset_worker",
            on_settled=self._shadow_offset_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_shadow_offset_busy(self, value: object) -> None:
        if not isinstance(value, RenderStyleShadowOffsetWorkerBusyState):
            raise TypeError(
                "busy signal must carry RenderStyleShadowOffsetWorkerBusyState"
            )
        model = self._shadow_offset_model
        command = model.state.worker_command if model is not None else None
        if (
            model is None
            or command is None
            or command.page_id != value.page_id
            or command.parent_id != value.parent_id
        ):
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @staticmethod
    def _shadow_offset_edit_matches_command(
        edit: Any,
        command: RenderStyleShadowOffsetWorkerCommand,
    ) -> bool:
        payload = dict(edit.payload)
        fields = payload.get("fields")
        if command.operation.value == "set":
            payload_matches = bool(
                command.shadow_offset is not None
                and set(payload) == {"fields"}
                and isinstance(fields, Mapping)
                and dict(fields) == {"shadow_offset": command.shadow_offset}
            )
            edit_operation = "set_fields"
        else:
            payload_matches = bool(
                command.shadow_offset is None
                and set(payload) == {"fields"}
                and isinstance(fields, tuple)
                and fields == ("shadow_offset",)
            )
            edit_operation = "restore_automatic"
        return bool(
            edit.domain is EditDomain.RENDER_STYLE
            and edit.operation == edit_operation
            and edit.page_id == command.page_id
            and edit.target.kind is EditTargetKind.PARENT
            and edit.target.parent_id == command.parent_id
            and not edit.target.artifact_id
            and not edit.target.edit_id
            and payload_matches
        )

    def _shadow_offset_receipt_matches_command(
        self,
        value: RenderStyleShadowOffsetWorkerReceipt,
        model: RenderStyleShadowOffsetEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        receipt = value.command_receipt
        if command is None:
            return False
        if command.operation.value == "set":
            after_matches = bool(
                command.shadow_offset is not None
                and receipt.after_shadow_offset == command.shadow_offset
                and receipt.after_shadow_offset_authority == "user"
            )
        else:
            after_matches = bool(
                command.shadow_offset is None
                and receipt.after_shadow_offset
                == receipt.automatic_shadow_offset
                and receipt.after_shadow_offset_authority == "automatic"
            )
        edit = receipt.edit
        commit = receipt.commit_receipt
        return bool(
            self._shadow_offset_edit_matches_command(edit, command)
            and receipt.command_id == edit.edit_id == commit.transaction_id
            and receipt.superseded_edit_id == edit.supersedes_edit_id
            and commit.page_id == command.page_id == edit.page_id
            and commit.edit_ids == (edit.edit_id,)
            and commit.artifact_revision_ids == ()
            and command.expected_effective_page_fingerprint
            == receipt.before_effective_page_fingerprint
            and receipt.automatic_shadow_offset
            == state.selection.automatic_shadow_offset
            and receipt.before_shadow_offset
            == state.selection.effective_shadow_offset
            and receipt.before_shadow_offset_authority
            == state.selection.shadow_offset_authority
            and after_matches
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(
                os.path.abspath(state.selection.project_path)
            )
        )

    def _shadow_offset_receipt_matches_current(
        self,
        value: RenderStyleShadowOffsetWorkerReceipt,
        model: RenderStyleShadowOffsetEditorModel,
    ) -> bool:
        if not self._shadow_offset_receipt_matches_command(value, model):
            return False
        state = model.state
        command = state.worker_command
        if command is None or self._projection is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        project_record = value.project.get("project")
        returned_project_id = (
            str(project_record.get("project_id") or "")
            if isinstance(project_record, Mapping)
            else ""
        )
        try:
            current_parent = self._projection.page(command.page_id).parent(
                command.parent_id
            )
        except (KeyError, ValueError):
            return False
        return bool(
            current_parent.automatic_shadow_offset
            == receipt.automatic_shadow_offset
            and current_parent.effective_shadow_offset
            == receipt.before_shadow_offset
            and current_parent.shadow_offset_authority
            == receipt.before_shadow_offset_authority
            and self._selected_page_id == command.page_id
            and self._selected_parent_id == command.parent_id
            and active_path
            == os.path.normcase(os.path.abspath(command.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(
                os.path.abspath(application_project.project_path)
            )
            == active_path
            and value.projection.metadata.project_id == edit.project_id
            and returned_project_id == edit.project_id
        )

    @QtCore.Slot(object)
    def _accept_shadow_offset_receipt(self, value: object) -> None:
        if not isinstance(value, RenderStyleShadowOffsetWorkerReceipt):
            raise TypeError(
                "receipt signal must carry RenderStyleShadowOffsetWorkerReceipt"
            )
        model = self._shadow_offset_model
        if model is None or not self._shadow_offset_receipt_matches_current(
            value,
            model,
        ):
            if (
                model is not None
                and self._shadow_offset_receipt_matches_command(value, model)
            ):
                active_command = model.state.worker_command
                if active_command is not None:
                    model.accept_stale(
                        RenderStyleShadowOffsetWorkerFailure(
                            code=(
                                RenderStyleShadowOffsetWorkerFailureCode.SNAPSHOT_STALE
                            ),
                            stage=RenderStyleShadowOffsetWorkerStage.COMPLETE,
                            project_path=active_command.project_path,
                            page_id=active_command.page_id,
                            parent_id=active_command.parent_id,
                            operation=active_command.operation,
                            shadow_offset=active_command.shadow_offset,
                            message=(
                                "The shadow-offset edit was saved, but the active "
                                "project changed. Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
                    self._refresh_target_text_editor()
                    self._refresh_run_presentation()
            self._set_notice(
                "A shadow-offset edit finished for a project that is no longer "
                "active. Reopen that project to inspect the saved edit.",
                warning=True,
            )
            return
        model.accept_receipt(value)
        receipt = value.command_receipt
        selected_page = receipt.edit.page_id
        selected_parent = receipt.edit.target.parent_id
        self._project, self._projection = dict(value.project), value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "Shadow offset saved. Preview this page explicitly to render the change."
        )

    def _shadow_offset_event_matches_active(
        self,
        value: (
            RenderStyleShadowOffsetWorkerFailure
            | RenderStyleShadowOffsetCancelledReceipt
        ),
    ) -> bool:
        model = self._shadow_offset_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        return bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.operation is value.operation
            and command.shadow_offset == value.shadow_offset
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value.project_path))
        )

    @QtCore.Slot(object)
    def _accept_shadow_offset_stale(self, value: object) -> None:
        if not isinstance(value, RenderStyleShadowOffsetWorkerFailure):
            raise TypeError(
                "stale signal must carry RenderStyleShadowOffsetWorkerFailure"
            )
        if not self._shadow_offset_event_matches_active(value):
            return
        model = self._shadow_offset_model
        if model is None:
            return
        model.accept_stale(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

    @QtCore.Slot(object)
    def _accept_shadow_offset_failure(self, value: object) -> None:
        if not isinstance(value, RenderStyleShadowOffsetWorkerFailure):
            raise TypeError(
                "failure signal must carry RenderStyleShadowOffsetWorkerFailure"
            )
        if not self._shadow_offset_event_matches_active(value):
            return
        model = self._shadow_offset_model
        if model is None:
            return
        model.accept_failure(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

    @QtCore.Slot(object)
    def _accept_shadow_offset_cancelled(self, value: object) -> None:
        if not isinstance(value, RenderStyleShadowOffsetCancelledReceipt):
            raise TypeError(
                "cancelled signal must carry RenderStyleShadowOffsetCancelledReceipt"
            )
        if not self._shadow_offset_event_matches_active(value):
            return
        model = self._shadow_offset_model
        if model is None:
            return
        model.accept_cancelled(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message)

    @QtCore.Slot()
    def _shadow_offset_thread_finished(self) -> None:
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    def _refresh_shadow_offset_editor(self) -> None:
        model = self._shadow_offset_model
        if model is None:
            if not self._selected_parent_id:
                self.editor.set_shadow_offset_editor_state(
                    automatic_shadow_offset=None,
                    user_shadow_offset=None,
                    effective_shadow_offset=None,
                    draft_shadow_offset=None,
                    shadow_offset_authority="automatic",
                    render_required=False,
                    editing_enabled=False,
                    apply_enabled=False,
                    cancel_enabled=False,
                    restore_enabled=False,
                    busy=False,
                    status_text=(
                        "Select a render-required parent to edit shadow offset"
                    ),
                    status_tone=PresentationTone.MUTED.value,
                )
            self._refresh_shadow_visibility_editor()
            return
        state = model.state
        mutation_allowed = self._shadow_offset_mutation_allowed()
        status_text = state.status_text
        status_tone = _SHADOW_OFFSET_TONES[state.phase]
        source_state = (
            self._source_text_model.state
            if self._source_text_model is not None
            else None
        )
        target_state = (
            self._target_text_model.state
            if self._target_text_model is not None
            else None
        )
        membership_state = (
            self._parent_membership_model.state
            if self._parent_membership_model is not None
            else None
        )
        geometry_state = (
            self._parent_geometry_model.state
            if self._parent_geometry_model is not None
            else None
        )
        reading_order_state = (
            self._reading_order_model.state
            if self._reading_order_model is not None
            else None
        )
        writing_mode_state = (
            self._writing_mode_model.state
            if self._writing_mode_model is not None
            else None
        )
        history_state = (
            self._edit_history_model.state
            if self._edit_history_model is not None
            else None
        )
        if not state.busy and self._project_thread is not None:
            status_text = "Shadow-offset editing is paused while another project opens."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and self._application_model.state.pipeline_busy:
            status_text = "Shadow-offset editing is paused while a run is active."
            status_tone = PresentationTone.MUTED.value
        elif not state.busy and not self._active_project_matches_projection():
            status_text = "Reload the active project before editing shadow offset."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and history_state is not None
            and not history_state.stable_for_run
        ):
            status_text = (
                "Reload the active project before editing shadow offset."
                if history_state.stale
                else "Wait for the edit-history action before editing shadow offset."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and source_state is not None
            and not source_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing shadow offset."
                if source_state.stale
                else "Apply or Cancel the source-text draft before editing shadow offset."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and target_state is not None
            and not target_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing shadow offset."
                if target_state.phase is TargetTextEditorPhase.STALE
                else "Apply or Cancel the target-text draft before editing shadow offset."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and membership_state is not None
            and not membership_state.stable_for_run
        ):
            status_text = "Reload the selected parent before editing shadow offset."
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and geometry_state is not None
            and not geometry_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing shadow offset."
                if geometry_state.stale
                else "Apply or Cancel the geometry draft before editing shadow offset."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and reading_order_state is not None
            and not reading_order_state.stable_for_run
        ):
            status_text = (
                "Reload the selected page before editing shadow offset."
                if reading_order_state.stale
                else "Apply or Cancel the reading-order draft before editing shadow offset."
            )
            status_tone = PresentationTone.WARNING.value
        elif (
            not state.busy
            and writing_mode_state is not None
            and not writing_mode_state.stable_for_run
        ):
            status_text = (
                "Reload the selected parent before editing shadow offset."
                if writing_mode_state.stale
                else "Set or Cancel the writing-mode draft before editing shadow offset."
            )
            status_tone = PresentationTone.WARNING.value
        elif not state.busy and not mutation_allowed:
            status_text = (
                "Resolve the active editor command before editing shadow offset."
            )
            status_tone = PresentationTone.WARNING.value
        self.editor.set_shadow_offset_editor_state(
            automatic_shadow_offset=state.selection.automatic_shadow_offset,
            user_shadow_offset=state.selection.user_shadow_offset,
            effective_shadow_offset=state.selection.effective_shadow_offset,
            draft_shadow_offset=state.draft_shadow_offset,
            shadow_offset_authority=state.selection.shadow_offset_authority,
            render_required=state.selection.render_required,
            editing_enabled=state.editing_enabled and mutation_allowed,
            apply_enabled=state.apply_enabled and mutation_allowed,
            cancel_enabled=state.cancel_enabled,
            restore_enabled=state.restore_enabled and mutation_allowed,
            busy=state.busy,
            status_text=status_text,
            status_tone=status_tone,
        )
        self._refresh_shadow_visibility_editor()

    @QtCore.Slot(bool)

    def _set_shadow_visibility_draft(self, visible: bool) -> None:
        model = self._shadow_visibility_model
        if model is None or not self._shadow_visibility_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before changing shadow visibility.",
                warning=True,
            )
            self._refresh_shadow_visibility_editor()
            return
        if visible:
            self._set_notice(
                "This editor cannot create or enable a shadow. Use Restore Automatic "
                "to remove a saved Hidden edit.",
                warning=True,
            )
            self._refresh_shadow_visibility_editor()
            return
        try:
            model.set_draft_shadow_enabled(False)
        except (RuntimeError, TypeError, ValueError) as exc:
            self._set_notice(str(exc), warning=True)
            self._refresh_shadow_visibility_editor()
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _cancel_shadow_visibility_draft(self) -> None:
        model = self._shadow_visibility_model
        if model is None or model.state.busy:
            return
        try:
            model.cancel_draft()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

    @QtCore.Slot()
    def _apply_shadow_visibility_draft(self) -> None:
        model = self._shadow_visibility_model
        if model is None or not self._shadow_visibility_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before hiding the shadow.",
                warning=True,
            )
            return
        try:
            command = model.begin_set()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_shadow_visibility_worker(command)

    @QtCore.Slot()
    def _restore_automatic_shadow_visibility(self) -> None:
        model = self._shadow_visibility_model
        if model is None or not self._shadow_visibility_mutation_allowed():
            self._set_notice(
                "Finish the active editor command before restoring shadow visibility.",
                warning=True,
            )
            return
        try:
            command = model.begin_restore()
        except RuntimeError as exc:
            self._set_notice(str(exc), warning=True)
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._start_shadow_visibility_worker(command)

    def _start_shadow_visibility_worker(
        self,
        command: RenderStyleShadowVisibilityWorkerCommand,
    ) -> None:
        if not isinstance(command, RenderStyleShadowVisibilityWorkerCommand):
            raise TypeError(
                "command must be RenderStyleShadowVisibilityWorkerCommand"
            )
        if self._shadow_visibility_thread is not None:
            raise RuntimeError("a shadow-visibility worker is already active")
        if not self._shadow_visibility_mutation_allowed():
            raise RuntimeError("shadow visibility is not currently editable")
        thread = QtCore.QThread(self)
        worker = RenderStyleShadowVisibilityWorker(command)
        worker.moveToThread(thread)
        thread.started.connect(
            worker.run,
            QtCore.Qt.ConnectionType.QueuedConnection,
        )
        worker.busy.connect(self._accept_shadow_visibility_busy)
        worker.receipt.connect(self._accept_shadow_visibility_receipt)
        worker.stale.connect(self._accept_shadow_visibility_stale)
        worker.failure.connect(self._accept_shadow_visibility_failure)
        worker.cancelled.connect(self._accept_shadow_visibility_cancelled)
        self._wire_one_shot_thread(
            thread=thread,
            worker=worker,
            thread_attribute="_shadow_visibility_thread",
            worker_attribute="_shadow_visibility_worker",
            on_settled=self._shadow_visibility_thread_finished,
        )
        thread.start()

    @QtCore.Slot(object)
    def _accept_shadow_visibility_busy(self, value: object) -> None:
        if not isinstance(value, RenderStyleShadowVisibilityWorkerBusyState):
            raise TypeError(
                "busy signal must carry RenderStyleShadowVisibilityWorkerBusyState"
            )
        model = self._shadow_visibility_model
        command = model.state.worker_command if model is not None else None
        if (
            model is None
            or command is None
            or command.page_id != value.page_id
            or command.parent_id != value.parent_id
        ):
            return
        try:
            model.accept_busy(value)
        except (RuntimeError, ValueError):
            return
        self._refresh_target_text_editor()
        self._refresh_run_presentation()

