    def _shadow_visibility_receipt_matches_command(
        self,
        value: RenderStyleShadowVisibilityWorkerReceipt,
        model: RenderStyleShadowVisibilityEditorModel,
    ) -> bool:
        state = model.state
        command = state.worker_command
        receipt = value.command_receipt
        if command is None:
            return False
        after_matches = (
            receipt.after_shadow_enabled is False
            and receipt.after_shadow_enabled_authority == "user"
            if command.operation.value == "hide"
            else receipt.after_shadow_enabled is True
            and receipt.after_shadow_enabled_authority == "automatic"
        )
        edit = receipt.edit
        commit = receipt.commit_receipt
        return bool(
            self._shadow_visibility_edit_matches_command(edit, command)
            and receipt.command_id == edit.edit_id == commit.transaction_id
            and receipt.superseded_edit_id == edit.supersedes_edit_id
            and commit.page_id == command.page_id == edit.page_id
            and commit.edit_ids == (edit.edit_id,)
            and commit.artifact_revision_ids == ()
            and command.expected_effective_page_fingerprint
            == receipt.before_effective_page_fingerprint
            and receipt.automatic_shadow_enabled
            is state.selection.automatic_shadow_enabled
            and receipt.before_shadow_enabled
            is state.selection.effective_shadow_enabled
            and receipt.before_shadow_enabled_authority
            == state.selection.shadow_enabled_authority
            and after_matches
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(state.selection.project_path))
        )

    def _shadow_visibility_receipt_matches_current(
        self,
        value: RenderStyleShadowVisibilityWorkerReceipt,
        model: RenderStyleShadowVisibilityEditorModel,
    ) -> bool:
        if not self._shadow_visibility_receipt_matches_command(value, model):
            return False
        command = model.state.worker_command
        if command is None or self._projection is None:
            return False
        receipt = value.command_receipt
        edit = receipt.edit
        metadata = getattr(self._projection, "metadata", None)
        application_project = self._application_model.state.project
        active_path = os.path.normcase(os.path.abspath(self._project_path))
        project_record = value.project.get("project")
        returned_project_id = (
            str(project_record.get("project_id") or "")
            if isinstance(project_record, Mapping)
            else ""
        )
        try:
            current_parent = self._projection.page(command.page_id).parent(
                command.parent_id
            )
        except (KeyError, ValueError):
            return False
        return bool(
            current_parent.automatic_shadow_enabled
            is receipt.automatic_shadow_enabled
            and current_parent.effective_shadow_enabled
            is receipt.before_shadow_enabled
            and current_parent.shadow_enabled_authority
            == receipt.before_shadow_enabled_authority
            and self._selected_page_id == command.page_id
            and self._selected_parent_id == command.parent_id
            and active_path
            == os.path.normcase(os.path.abspath(command.project_path))
            and active_path
            == os.path.normcase(
                os.path.abspath(value.projection.metadata.project_path)
            )
            and getattr(metadata, "project_id", "") == edit.project_id
            and application_project.project_id == edit.project_id
            and os.path.normcase(
                os.path.abspath(application_project.project_path)
            )
            == active_path
            and value.projection.metadata.project_id == edit.project_id
            and returned_project_id == edit.project_id
        )

    @QtCore.Slot(object)
    def _accept_shadow_visibility_receipt(self, value: object) -> None:
        if not isinstance(value, RenderStyleShadowVisibilityWorkerReceipt):
            raise TypeError(
                "receipt signal must carry RenderStyleShadowVisibilityWorkerReceipt"
            )
        model = self._shadow_visibility_model
        if model is None or not self._shadow_visibility_receipt_matches_current(
            value, model
        ):
            if (
                model is not None
                and self._shadow_visibility_receipt_matches_command(value, model)
            ):
                command = model.state.worker_command
                if command is not None:
                    model.accept_stale(
                        RenderStyleShadowVisibilityWorkerFailure(
                            code=RenderStyleShadowVisibilityWorkerFailureCode.SNAPSHOT_STALE,
                            stage=RenderStyleShadowVisibilityWorkerStage.COMPLETE,
                            project_path=command.project_path,
                            page_id=command.page_id,
                            parent_id=command.parent_id,
                            operation=command.operation,
                            shadow_enabled=command.shadow_enabled,
                            message=(
                                "The shadow-visibility edit was saved, but the active "
                                "project changed. Reopen the project before continuing."
                            ),
                            persistence_committed=True,
                            command_receipt=value.command_receipt,
                        )
                    )
            self._set_notice(
                "A shadow-visibility edit finished for a project that is no longer "
                "active. Reopen that project to inspect the saved edit.",
                warning=True,
            )
            self._refresh_target_text_editor()
            self._refresh_run_presentation()
            return
        model.accept_receipt(value)
        receipt = value.command_receipt
        selected_page = receipt.edit.page_id
        selected_parent = receipt.edit.target.parent_id
        self._project, self._projection = dict(value.project), value.projection
        self._page_model.replace_rows(value.projection.page_rows)
        metadata = value.projection.metadata
        self.workspace.set_project_summary(
            title=metadata.name,
            language_pair=f"{metadata.source_language} → {metadata.target_language}",
            page_count=metadata.page_count,
        )
        self.editor.set_project_name(metadata.name)
        self._refresh_recent_projects(current=value.projection.project_row)
        self._selected_page_id = selected_page
        self._selected_parent_id = selected_parent
        self.select_page(selected_page)
        self._refresh_navigation()
        self._refresh_run_presentation()
        self._refresh_activity()
        self._set_notice(
            "Shadow visibility saved. Preview this page explicitly to render the change."
        )

    def _shadow_visibility_event_matches_active(
        self,
        value: (
            RenderStyleShadowVisibilityWorkerFailure
            | RenderStyleShadowVisibilityCancelledReceipt
        ),
    ) -> bool:
        model = self._shadow_visibility_model
        command = model.state.worker_command if model is not None else None
        if command is None:
            return False
        return bool(
            command.page_id == value.page_id
            and command.parent_id == value.parent_id
            and command.operation is value.operation
            and command.shadow_enabled is value.shadow_enabled
            and os.path.normcase(os.path.abspath(command.project_path))
            == os.path.normcase(os.path.abspath(value.project_path))
        )

    @QtCore.Slot(object)
    def _accept_shadow_visibility_stale(self, value: object) -> None:
        if not isinstance(value, RenderStyleShadowVisibilityWorkerFailure):
            raise TypeError(
                "stale signal must carry RenderStyleShadowVisibilityWorkerFailure"
            )
        if not self._shadow_visibility_event_matches_active(value):
            return
        model = self._shadow_visibility_model
        if model is None:
            return
        model.accept_stale(value)
        self._refresh_target_text_editor()
        self._refresh_run_presentation()
        self._set_notice(value.message, warning=True)

